INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (4,170,'An-Nisaa','يَٰٓأَيُّهَا ٱلنَّاسُ قَدۡ جَآءَكُمُ ٱلرَّسُولُ بِٱلۡحَقِّ مِن رَّبِّكُمۡ فَـَٔامِنُواْ خَيۡرࣰ ا لَّكُمۡۚ وَإِن تَكۡفُرُواْ فَإِنَّ لِلَّهِ مَا فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۚ وَكَانَ ٱللَّهُ عَلِيمًا حَكِيمࣰ ا','لوگو! خدا کے پیغمبر تمہارے پاس تمہارے پروردگار کی طرف سے حق بات لے کر آئے ہیں تو (ان پر) ایمان لاؤ (یہی) تمہارے حق میں بہتر ہے۔ اور اگر کفر کرو گے تو (جان رکھو کہ) جو کچھ آسمانوں اور زمین میں ہے سب خداہی کا ہے اور خدا سب کچھ جاننے والا (اور) حکمت والا ہے','O humanity! The Messenger has certainly come to you with the truth from your Lord, so believe for your own good. But if you disbelieve, then ˹know that˺ to Allah belongs whatever is in the heavens and the earth. And Allah is All-Knowing, All-Wise','ऐ लोगों तुम्हारे पास तुम्हारे परवरदिगार की तरफ़ से रसूल (मोहम्मद) दीने हक़ के साथ आ चुके हैं ईमान लाओ (यही) तुम्हारे हक़ में बेहतर है और अगर इन्कार करोगे तो (समझ रखो कि) जो कुछ ज़मीन और आसमानों में है सब ख़ुदा ही का है और ख़ुदा बड़ा वाक़िफ़कार हकीम है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (4,171,'An-Nisaa','يَٰٓأَهۡلَ ٱلۡكِتَٰبِ لَا تَغۡلُواْ فِي دِينِكُمۡ وَلَا تَقُولُواْ عَلَى ٱللَّهِ إِلَّا ٱلۡحَقَّۚ إِنَّمَا ٱلۡمَسِيحُ عِيسَى ٱبۡنُ مَرۡيَمَ رَسُولُ ٱللَّهِ وَكَلِمَتُهُۥٓ أَلۡقَىٰهَآ إِلَىٰ مَرۡيَمَ وَرُوحࣱ مِّنۡهُۖ فَـَٔامِنُواْ بِٱللَّهِ وَرُسُلِهِۦۖ وَلَا تَقُولُواْ ثَلَٰثَةٌۚ ٱنتَهُواْ خَيۡرࣰ ا لَّكُمۡۚ إِنَّمَا ٱللَّهُ إِلَٰهࣱ وَٰحِدࣱۖ سُبۡحَٰنَهُۥٓ أَن يَكُونَ لَهُۥ وَلَدࣱۘ لَّهُۥ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِۗ وَكَفَىٰ بِٱللَّهِ وَكِيلࣰ ا','اے اہل کتاب اپنے دین (کی بات) میں حد سے نہ بڑھو اور خدا کے بارے میں حق کے سوا کچھ نہ کہو۔ مسیح (یعنی) مریم کے بیٹے عیسیٰ (نہ خدا تھے نہ خدا کے بیٹے بلکہ) خدا کے رسول اور کا کلمہٴ (بشارت) تھے جو اس نے مریم کی طرف بھیجا تھا اور اس کی طرف سے ایک روح تھے تو خدا اوراس کے رسولوں پر ایمان لاؤ۔ اور (یہ) نہ کہو (کہ خدا) تین (ہیں۔ اس اعتقاد سے) باز آؤ کہ یہ تمہارے حق میں بہتر ہے۔ خدا ہی معبود واحد ہے اور اس سے پاک ہے کہ اس کے اولاد ہو۔ جو کچھ آسمانوں میں اور جو کچھ زمین میں ہے سب اسی کا ہے۔ اور خدا ہی کارساز کافی ہے','O People of the Book! Do not go to extremes regarding your faith; say nothing about Allah except the truth. The Messiah, Jesus, son of Mary, was no more than a messenger of Allah and the fulfilment of His Word through Mary and a spirit ˹created by a command˺ from Him. So believe in Allah and His messengers and do not say, “Trinity.” Stop!—for your own good. Allah is only One God. Glory be to Him! He is far above having a son! To Him belongs whatever is in the heavens and whatever is on the earth. And Allah is sufficient as a Trustee of Affairs','ऐ अहले किताब अपने दीन में हद (एतदाल) से तजावुज़ न करो और ख़ुदा की शान में सच के सिवा (कोई दूसरी बात) न कहो मरियम के बेटे ईसा मसीह (न ख़ुदा थे न ख़ुदा के बेटे) पस ख़ुदा के एक रसूल और उसके कलमे (हुक्म) थे जिसे ख़ुदा ने मरियम के पास भेज दिया था (कि हामला हो जा) और ख़ुदा की तरफ़ से एक जान थे पस ख़ुदा और उसके रसूलों पर ईमान लाओ और तीन (ख़ुदा) के क़ायल न बनो (तसलीस से) बाज़ रहो (और) अपनी भलाई (तौहीद) का क़सद करो अल्लाह तो बस यकता माबूद है वह उस (नुक्स) से पाक व पाकीज़ा है उसका कोई लड़का हो (उसे लड़के की हाजत ही क्या है) जो कुछ आसमानों में है और जो कुछ ज़मीन में है सब तो उसी का है और ख़ुदा तो कारसाज़ी में काफ़ी है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (4,172,'An-Nisaa','لَّن يَسۡتَنكِفَ ٱلۡمَسِيحُ أَن يَكُونَ عَبۡدࣰ ا لِّلَّهِ وَلَا ٱلۡمَلَٰٓئِكَةُ ٱلۡمُقَرَّبُونَۚ وَمَن يَسۡتَنكِفۡ عَنۡ عِبَادَتِهِۦ وَيَسۡتَكۡبِرۡ فَسَيَحۡشُرُهُمۡ إِلَيۡهِ جَمِيعࣰ ا','مسیح اس بات سے عار نہیں رکھتے کہ خدا کے بندے ہوں اور نہ مقرب فرشتے (عار رکھتے ہیں) اور جو شخص خدا کا بندہ ہونے کو موجب عار سمجھے اور سرکشی کرے تو خدا سب کو اپنے پاس جمع کرلے گا','The Messiah would never be too proud to be a servant of Allah, nor would the angels nearest to Allah. Those who are too proud and arrogant to worship Him will be brought before Him all together','न तो मसीह ही ख़ुदा का बन्दा होने से हरगिज़ इन्कार कर सकते हैं और न (ख़ुदा के) मुक़र्रर फ़रिश्ते और (याद रहे) जो शख्स उसके बन्दा होने से इन्कार करेगा और शेख़ी करेगा तो अनक़रीब ही ख़ुदा उन सबको अपनी तरफ़ उठा लेगा (और हर एक को उसके काम की सज़ा देगा)');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (4,173,'An-Nisaa','فَأَمَّا ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ فَيُوَفِّيهِمۡ أُجُورَهُمۡ وَيَزِيدُهُم مِّن فَضۡلِهِۦۖ وَأَمَّا ٱلَّذِينَ ٱسۡتَنكَفُواْ وَٱسۡتَكۡبَرُواْ فَيُعَذِّبُهُمۡ عَذَابًا أَلِيمࣰ ا وَلَا يَجِدُونَ لَهُم مِّن دُونِ ٱللَّهِ وَلِيࣰّ ا وَلَا نَصِيرࣰ ا','تو جو لوگ ایمان لائے اور نیک کام کرتے رہے وہ ان کو ان کا پورا بدلا دے گا اور اپنے فضل سے کچھ زیادہ بھی عنایت کرے گا۔ اور جنہوں نے (بندوں ہونے سے) عاروانکار اور تکبر کیا ان کو تکلیف دینے والا عذاب دے گا۔ اور یہ لوگ خدا کے سوا اپنا حامی اور مددگار نہ پائیں گے','As for those who believe and do good, He will reward them in full and increase them out of His grace. But those who are too proud and arrogant, He will subject them to a painful punishment. And besides Allah they will find no protector or helper','पस जिन लोगों ने ईमान कुबूल किया है और अच्छे (अच्छे) काम किए हैं उनका उन्हें सवाब पूरा पूरा भर देगा बल्कि अपने फ़ज़ल (व करम) से कुछ और ज्यादा ही देगा और लोग उसका बन्दा होने से इन्कार करते थे और शेख़ी करते थे उन्हें तो दर्दनाक अज़ाब में मुब्तिला करेगा और लुत्फ़ ये है कि वह लोग ख़ुदा के सिवा न अपना सरपरस्त ही पाएंगे और न मददगार');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (4,174,'An-Nisaa','يَٰٓأَيُّهَا ٱلنَّاسُ قَدۡ جَآءَكُم بُرۡهَٰنࣱ مِّن رَّبِّكُمۡ وَأَنزَلۡنَآ إِلَيۡكُمۡ نُورࣰ ا مُّبِينࣰ ا','لوگو تمہارے پروردگار کی طرف سے تمہارے پاس دلیل (روشن) آچکی ہے اور ہم نے (کفر اور ضلالت کا اندھیرا دور کرنے کو) تمہاری طرف چمکتا ہوا نور بھیج دیا ہے','O humanity! There has come to you conclusive evidence from your Lord. And We have sent down to you a brilliant light','ऐ लोगों इसमें तो शक ही नहीं कि तुम्हारे परवरदिगार की तरफ़ से (दीने हक़ की) दलील आ चुकी और हम तुम्हारे पास एक चमकता हुआ नूर नाज़िल कर चुके हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (4,175,'An-Nisaa','فَأَمَّا ٱلَّذِينَ ءَامَنُواْ بِٱللَّهِ وَٱعۡتَصَمُواْ بِهِۦ فَسَيُدۡخِلُهُمۡ فِي رَحۡمَةࣲ مِّنۡهُ وَفَضۡلࣲ وَيَهۡدِيهِمۡ إِلَيۡهِ صِرَٰطࣰ ا مُّسۡتَقِيمࣰ ا','پس جو لوگ خدا پر ایمان لائے اور اس (کے دین کی رسی) کو مضبوط پکڑے رہے ان کو وہ اپنی رحمت اور فضل (کے بہشتوں) میں داخل کرے گا۔ اور اپنی طرف (پہچنے کا) سیدھا رستہ دکھائے گا','As for those who believe in Allah and hold fast to Him, He will admit them into His mercy and grace and guide them to Himself through the Straight Path','पस जो लोग ख़ुदा पर ईमान लाए और उसी से लगे लिपटे रहे तो ख़ुदा भी उन्हें अनक़रीब ही अपनी रहमत व फ़ज़ल के सादाब बाग़ो में पहुंचा देगा और उन्हे अपने हुज़ूरी का सीधा रास्ता दिखा देगा');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (4,176,'An-Nisaa','يَسۡتَفۡتُونَكَ قُلِ ٱللَّهُ يُفۡتِيكُمۡ فِي ٱلۡكَلَٰلَةِۚ إِنِ ٱمۡرُؤٌاْ هَلَكَ لَيۡسَ لَهُۥ وَلَدࣱ وَلَهُۥٓ أُخۡتࣱ فَلَهَا نِصۡفُ مَا تَرَكَۚ وَهُوَ يَرِثُهَآ إِن لَّمۡ يَكُن لَّهَا وَلَدࣱۚ فَإِن كَانَتَا ٱثۡنَتَيۡنِ فَلَهُمَا ٱلثُّلُثَانِ مِمَّا تَرَكَۚ وَإِن كَانُوٓاْ إِخۡوَةࣰ رِّجَالࣰ ا وَنِسَآءࣰ فَلِلذَّكَرِ مِثۡلُ حَظِّ ٱلۡأُنثَيَيۡنِۗ يُبَيِّنُ ٱللَّهُ لَكُمۡ أَن تَضِلُّواْۗ وَٱللَّهُ بِكُلِّ شَيۡءٍ عَلِيمُۢ','(اے پیغمبر) لوگ تم سے (کلالہ کے بارے میں) حکم (خدا) دریافت کرتے ہیں کہہ دو کہ خدا کلالہ بارے میں یہ حکم دیتا ہے کہ اگر کوئی ایسا مرد مرجائے جس کے اولاد نہ ہو (اور نہ ماں باپ) اور اس کے بہن ہو تو اس کو بھائی کے ترکے میں سے آدھا حصہ ملے گا۔ اور اگر بہن مرجائے اور اس کے اولاد نہ ہو تو اس کے تمام مال کا وارث بھائی ہوگا اور اگر (مرنے والے بھائی کی) دو بہنیں ہوں تو دونوں کو بھائی کے ترکے میں سے دو تہائی۔ اور اگر بھائی اور بہن یعنی مرد اور عورتیں ملے جلے وارث ہوں تو مرد کا حصہ دو عورتوں کے برابر ہے۔ (یہ احکام) خدا تم سے اس لئے بیان فرماتا ہے کہ بھٹکتے نہ پھرو۔ اور خدا ہر چیز سے واقف ہے','They ask you ˹for a ruling, O Prophet˺. Say, “Allah gives you a ruling regarding those who die without children or parents.” If a man dies childless and leaves behind a sister, she will inherit one-half of his estate, whereas her brother will inherit all of her estate if she dies childless. If this person leaves behind two sisters, they together will inherit two-thirds of the estate. But if the deceased leaves male and female siblings, a male’s share will be equal to that of two females. Allah makes ˹this˺ clear to you so you do not go astray. And Allah has ˹perfect˺ knowledge of all things','(ऐ रसूल) तुमसे लोग फ़तवा तलब करते हैं तुम कह दो कि कलाला (भाई बहन) के बारे में ख़ुदा तो ख़ुद तुम्हे फ़तवा देता है कि अगर कोई ऐसा शख्स मर जाए कि उसके न कोई लड़का बाला हो (न मॉ बाप) और उसके (सिर्फ) एक बहन हो तो उसका तर्के से आधा होगा (और अगर ये बहन मर जाए) और उसके कोई औलाद न हो (न मॉ बाप) तो उसका वारिस बस यही भाई होगा और अगर दो बहनें (ज्यादा) हों तो उनको (भाई के) तर्के से दो तिहाई मिलेगा और अगर किसी के वारिस भाई बहन दोनों (मिले जुले) हों तो मर्द को औरत के हिस्से का दुगना मिलेगा तुम लोगों के भटकने के ख्याल से ख़ुदा अपने एहकाम वाजेए करके बयान फ़रमाता है और ख़ुदा तो हर चीज़ से वाक़िफ़ है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (5,1,'Al-Maaida','يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ أَوۡفُواْ بِٱلۡعُقُودِۚ أُحِلَّتۡ لَكُم بَهِيمَةُ ٱلۡأَنۡعَٰمِ إِلَّا مَا يُتۡلَىٰ عَلَيۡكُمۡ غَيۡرَ مُحِلِّي ٱلصَّيۡدِ وَأَنتُمۡ حُرُمٌۗ إِنَّ ٱللَّهَ يَحۡكُمُ مَا يُرِيدُ','اے ایمان والو! اپنے اقراروں کو پورا کرو۔ تمہارے لیے چارپائے جانور (جو چرنے والے ہیں) حلال کر دیئے گئے ہیں۔ بجز ان کے جو تمہیں پڑھ کر سنائے جاتے ہیں مگر احرام (حج) میں شکار کو حلال نہ جاننا۔ خدا جیسا چاہتا ہے حکم دیتا ہے','O believers! Honour your obligations. All grazing livestock has been made lawful to you—except what is hereby announced to you and hunting while on pilgrimage. Indeed, Allah commands what He wills','ऐ ईमानदारों (अपने) इक़रारों को पूरा करो (देखो) तुम्हारे वास्ते चौपाए जानवर हलाल कर दिये गये उन के सिवा जो तुमको पढ़ कर सुनाए जाएंगे हलाल कर दिए गए मगर जब तुम हालते एहराम में हो तो शिकार को हलाल न समझना बेशक ख़ुदा जो चाहता है हुक्म देता है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (5,2,'Al-Maaida','يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تُحِلُّواْ شَعَٰٓئِرَ ٱللَّهِ وَلَا ٱلشَّهۡرَ ٱلۡحَرَامَ وَلَا ٱلۡهَدۡيَ وَلَا ٱلۡقَلَٰٓئِدَ وَلَآ ءَآمِّينَ ٱلۡبَيۡتَ ٱلۡحَرَامَ يَبۡتَغُونَ فَضۡلࣰ ا مِّن رَّبِّهِمۡ وَرِضۡوَٰنࣰ اۚ وَإِذَا حَلَلۡتُمۡ فَٱصۡطَادُواْۚ وَلَا يَجۡرِمَنَّكُمۡ شَنَـَٔانُ قَوۡمٍ أَن صَدُّوكُمۡ عَنِ ٱلۡمَسۡجِدِ ٱلۡحَرَامِ أَن تَعۡتَدُواْۘ وَتَعَاوَنُواْ عَلَى ٱلۡبِرِّ وَٱلتَّقۡوَىٰۖ وَلَا تَعَاوَنُواْ عَلَى ٱلۡإِثۡمِ وَٱلۡعُدۡوَٰنِۚ وَٱتَّقُواْ ٱللَّهَۖ إِنَّ ٱللَّهَ شَدِيدُ ٱلۡعِقَابِ','مومنو! خدا کے نام کی چیزوں کی بےحرمتی نہ کرنا اور نہ ادب کے مہینے کی اور نہ قربانی کے جانوروں کی اور نہ ان جانوروں کی (جو خدا کی نذر کر دیئے گئے ہوں اور) جن کے گلوں میں پٹے بندھے ہوں اور نہ ان لوگوں کی جو عزت کے گھر (یعنی بیت الله) کو جا رہے ہوں (اور) اپنے پروردگار کے فضل اور اس کی خوشنودی کے طلبگار ہوں اور جب احرام اتار دو تو (پھر اختیار ہے کہ) شکار کرو اور لوگوں کی دشمنی اس وجہ سے کہ انہوں نے تم کو عزت والی مسجد سے روکا تھا تمہیں اس بات پر آمادہ نہ کرے کہ تم ان پر زیادتی کرنے لگو اور (دیکھو) نیکی اور پرہیزگاری کے کاموں میں ایک دوسرے کی مدد کیا کرو اور گناہ اور ظلم کی باتوں میں مدد نہ کیا کرو اور خدا سے ڈرتے رہو۔ کچھ شک نہیں کہ خدا کا عذاب سخت ہے','O believers! Do not violate Allah’s rituals ˹of pilgrimage˺, the sacred months, the sacrificial animals, the ˹offerings decorated with˺ garlands, nor those ˹pilgrims˺ on their way to the Sacred House seeking their Lord’s bounty and pleasure. When pilgrimage has ended, you are allowed to hunt. Do not let the hatred of a people who once barred you from the Sacred Mosque provoke you to transgress. Cooperate with one another in goodness and righteousness, and do not cooperate in sin and transgression. And be mindful of Allah. Surely Allah is severe in punishment','ऐ ईमानदारों (देखो) न ख़ुदा की निशानियों की बेतौक़ीरी करो और न हुरमत वाले महिने की और न क़ुरबानी की और न पट्टे वाले जानवरों की (जो नज़रे ख़ुदा के लिए निशान देकर मिना में ले जाते हैं) और न ख़ानाए काबा की तवाफ़ (व ज़ियारत) का क़स्द करने वालों की जो अपने परवरदिगार की ख़ुशनूदी और फ़ज़ल (व करम) के जोयाँ हैं और जब तुम (एहराम) खोल दो तो शिकार कर सकते हो और किसी क़बीले की यह अदावत कि तुम्हें उन लोगों ने ख़ानाए काबा (में जाने) से रोका था इस जुर्म में न फॅसवा दे कि तुम उनपर ज्यादती करने लगो और (तुम्हारा तो फ़र्ज यह है कि ) नेकी और परहेज़गारी में एक दूसरे की मदद किया करो और गुनाह और ज्यादती में बाहम किसी की मदद न करो और ख़ुदा से डरते रहो (क्योंकि) ख़ुदा तो यक़ीनन बड़ा सख्त अज़ाब वाला है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (5,3,'Al-Maaida','حُرِّمَتۡ عَلَيۡكُمُ ٱلۡمَيۡتَةُ وَٱلدَّمُ وَلَحۡمُ ٱلۡخِنزِيرِ وَمَآ أُهِلَّ لِغَيۡرِ ٱللَّهِ بِهِۦ وَٱلۡمُنۡخَنِقَةُ وَٱلۡمَوۡقُوذَةُ وَٱلۡمُتَرَدِّيَةُ وَٱلنَّطِيحَةُ وَمَآ أَكَلَ ٱلسَّبُعُ إِلَّا مَا ذَكَّيۡتُمۡ وَمَا ذُبِحَ عَلَى ٱلنُّصُبِ وَأَن تَسۡتَقۡسِمُواْ بِٱلۡأَزۡلَٰمِۚ ذَٰلِكُمۡ فِسۡقٌۗ ٱلۡيَوۡمَ يَئِسَ ٱلَّذِينَ كَفَرُواْ مِن دِينِكُمۡ فَلَا تَخۡشَوۡهُمۡ وَٱخۡشَوۡنِۚ ٱلۡيَوۡمَ أَكۡمَلۡتُ لَكُمۡ دِينَكُمۡ وَأَتۡمَمۡتُ عَلَيۡكُمۡ نِعۡمَتِي وَرَضِيتُ لَكُمُ ٱلۡإِسۡلَٰمَ دِينࣰ اۚ فَمَنِ ٱضۡطُرَّ فِي مَخۡمَصَةٍ غَيۡرَ مُتَجَانِفࣲ لِّإِثۡمࣲ فَإِنَّ ٱللَّهَ غَفُورࣱ رَّحِيمࣱ‏','تم پر مرا ہوا جانور اور (بہتا) لہو اور سور کا گوشت اور جس چیز پر خدا کے سوا کسی اور کا نام پکارا جائے اور جو جانور گلا گھٹ کر مر جائے اور جو چوٹ لگ کر مر جائے اور جو گر کر مر جائے اور جو سینگ لگ کر مر جائے یہ سب حرام ہیں اور وہ جانور بھی جس کو درندے پھاڑ کھائیں۔ مگر جس کو تم (مرنے سے پہلے) ذبح کرلو اور وہ جانور بھی جو تھان پر ذبح کیا جائے اور یہ بھی کہ پاسوں سے قسمت معلوم کرو یہ سب گناہ (کے کام) ہیں آج کافر تمہارے دین سے ناامید ہو گئے ہیں تو ان سے مت ڈرو اور مجھی سے ڈرتے رہو (اور) آج ہم نے تمہارے لئے تمہارا دین کامل کر دیا اور اپنی نعمتیں تم پر پوری کر دیں اور تمہارے لئے اسلام کو دین پسند کیا ہاں جو شخص بھوک میں ناچار ہو جائے (بشرطیکہ) گناہ کی طرف مائل نہ ہو تو خدا بخشنے والا مہربان ہے','Forbidden to you are carrion, blood, and swine; what is slaughtered in the name of any other than Allah; what is killed by strangling, beating, a fall, or by being gored to death; what is partly eaten by a predator unless you slaughter it; and what is sacrificed on altars. You are also forbidden to draw lots for decisions. This is all evil. Today the disbelievers have given up all hope of ˹undermining˺ your faith. So do not fear them; fear Me! Today I have perfected your faith for you, completed My favour upon you, and chosen Islam as your way. But whoever is compelled by extreme hunger—not intending to sin—then surely Allah is All-Forgiving, Most Merciful','(लोगों) मरा हुआ जानवर और ख़ून और सुअर का गोश्त और जिस (जानवर) पर (ज़िबाह) के वक्त ख़ुदा के सिवा किसी दूसरे का नाम लिया जाए और गर्दन मरोड़ा हुआ और चोट खाकर मरा हुआ और जो कुएं (वगैरह) में गिरकर मर जाए और जो सींग से मार डाला गया हो और जिसको दरिन्दे ने फाड़ खाया हो मगर जिसे तुमने मरने के क़ब्ल ज़िबाह कर लो और (जो जानवर) बुतों (के थान) पर चढ़ा कर ज़िबाह किया जाए और जिसे तुम (पाँसे) के तीरों से बाहम हिस्सा बॉटो (ग़रज़ यह सब चीज़ें) तुम पर हराम की गयी हैं ये गुनाह की बात है (मुसलमानों) अब तो कुफ्फ़ार तुम्हारे दीन से (फिर जाने से) मायूस हो गए तो तुम उनसे तो डरो ही नहीं बल्कि सिर्फ मुझी से डरो आज मैंने तुम्हारे दीन को कामिल कर दिया और तुमपर अपनी नेअमत पूरी कर दी और तुम्हारे (इस) दीने इस्लाम को पसन्द किया पस जो शख्स भूख़ में मजबूर हो जाए और गुनाह की तरफ़ माएल भी न हो (और कोई चीज़ खा ले) तो ख़ुदा बेशक बड़ा बख्शने वाला मेहरबान है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (5,4,'Al-Maaida','يَسۡـَٔلُونَكَ مَاذَآ أُحِلَّ لَهُمۡۖ قُلۡ أُحِلَّ لَكُمُ ٱلطَّيِّبَٰتُ وَمَا عَلَّمۡتُم مِّنَ ٱلۡجَوَارِحِ مُكَلِّبِينَ تُعَلِّمُونَهُنَّ مِمَّا عَلَّمَكُمُ ٱللَّهُۖ فَكُلُواْ مِمَّآ أَمۡسَكۡنَ عَلَيۡكُمۡ وَٱذۡكُرُواْ ٱسۡمَ ٱللَّهِ عَلَيۡهِۖ وَٱتَّقُواْ ٱللَّهَۚ إِنَّ ٱللَّهَ سَرِيعُ ٱلۡحِسَابِ','تم سے پوچھتے ہیں کہ کون کون سی چیزیں ان کے لیے حلال ہیں (ان سے) کہہ دو کہ سب پاکیزہ چیزیں تم کو حلال ہیں اور وہ (شکار) بھی حلال ہے جو تمہارے لیے ان شکاری جانوروں نے پکڑا ہو جن کو تم نے سدھا رکھا ہو اور جس (طریق) سے خدا نے تمہیں (شکار کرنا) سکھایا ہے (اس طریق سے) تم نے ان کو سکھایا ہو تو جو شکار وہ تمہارے لئے پکڑ رکھیں اس کو کھا لیا کرو اور (شکاری جانوروں کو چھوڑتے وقت) خدا کا نام لے لیا کرو اور خدا سے ڈرتے رہو۔ بےشک خدا جلد حساب لینے والا ہے','They ask you, ˹O Prophet,˺ what is permissible for them ˹to eat˺. Say, “What is good and lawful. Also what is caught by your hunting animals and birds of prey which you have trained as instructed by Allah. So eat what they catch for you, but mention the Name of Allah over it ˹first˺.” And be mindful of Allah. Surely Allah is swift in reckoning','(ऐ रसूल) तुमसे लोग पूंछते हैं कि कौन (कौन) चीज़ उनके लिए हलाल की गयी है तुम (उनसे) कह दो कि तुम्हारे लिए पाकीज़ा चीजें हलाल की गयीं और शिकारी जानवर जो तुमने शिकार के लिए सधा रखें है और जो (तरीके) ख़ुदा ने तुम्हें बताये हैं उनमें के कुछ तुमने उन जानवरों को भी सिखाया हो तो ये शिकारी जानवर जिस शिकार को तुम्हारे लिए पकड़ रखें उसको (बेताम्मुल) खाओ और (जानवर को छोंड़ते वक्त) ख़ुदा का नाम ले लिया करो और ख़ुदा से डरते रहो (क्योंकि) इसमें तो शक ही नहीं कि ख़ुदा बहुत जल्द हिसाब लेने वाला है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (5,5,'Al-Maaida','ٱلۡيَوۡمَ أُحِلَّ لَكُمُ ٱلطَّيِّبَٰتُۖ وَطَعَامُ ٱلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ حِلࣱّ لَّكُمۡ وَطَعَامُكُمۡ حِلࣱّ لَّهُمۡۖ وَٱلۡمُحۡصَنَٰتُ مِنَ ٱلۡمُؤۡمِنَٰتِ وَٱلۡمُحۡصَنَٰتُ مِنَ ٱلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ مِن قَبۡلِكُمۡ إِذَآ ءَاتَيۡتُمُوهُنَّ أُجُورَهُنَّ مُحۡصِنِينَ غَيۡرَ مُسَٰفِحِينَ وَلَا مُتَّخِذِيٓ أَخۡدَانࣲۗ وَمَن يَكۡفُرۡ بِٱلۡإِيمَٰنِ فَقَدۡ حَبِطَ عَمَلُهُۥ وَهُوَ فِي ٱلۡأٓخِرَةِ مِنَ ٱلۡخَٰسِرِينَ','آج تمہارے لیے سب پاکیزہ چیزیں حلال کر دی گئیں اور اہل کتاب کا کھانا بھی تم کو حلال ہے اور تمہارا کھانا ان کو حلال ہے اور پاک دامن مومن عورتیں اور پاک دامن اہل کتاب عورتیں بھی (حلال ہیں) جبکہ ان کا مہر دے دو۔ اور ان سے عفت قائم رکھنی مقصود ہو نہ کھلی بدکاری کرنی اور نہ چھپی دوستی کرنی اور جو شخص ایمان سے منکر ہوا اس کے عمل ضائع ہو گئے اور وہ آخرت میں نقصان پانے والوں میں ہوگا','Today all good, pure foods have been made lawful for you. Similarly, the food of the People of the Book is permissible for you and yours is permissible for them. And ˹permissible for you in marriage˺ are chaste believing women as well as chaste women of those given the Scripture before you—as long as you pay them their dowries in wedlock, neither fornicating nor taking them as mistresses. And whoever rejects the faith, all their good deeds will be void ˹in this life˺ and in the Hereafter they will be among the losers','आज तमाम पाकीज़ा चीजें तुम्हारे लिए हलाल कर दी गयी हैं और अहले किताब की ख़ुश्क चीजें ग़ेहूं (वगैरह) तुम्हारे लिए हलाल हैं और तुम्हारी ख़ुश्क चीजें ग़ेहूं (वगैरह) उनके लिए हलाल हैं और आज़ाद पाक दामन औरतें और उन लोगों में की आज़ाद पाक दामन औरतें जिनको तुमसे पहले किताब दी जा चुकी है जब तुम उनको उनके मेहर दे दो (और) पाक दामिनी का इरादा करो न तो खुल्लम खुल्ला ज़िनाकारी का और न चोरी छिपे से आशनाई का और जिस शख्स ने ईमान से इन्कार किया तो उसका सब किया (धरा) अकारत हो गया और (तुल्फ़ तो ये है कि) आख़ेरत में भी वही घाटे में रहेगा');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (5,6,'Al-Maaida','يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ إِذَا قُمۡتُمۡ إِلَى ٱلصَّلَوٰةِ فَٱغۡسِلُواْ وُجُوهَكُمۡ وَأَيۡدِيَكُمۡ إِلَى ٱلۡمَرَافِقِ وَٱمۡسَحُواْ بِرُءُوسِكُمۡ وَأَرۡجُلَكُمۡ إِلَى ٱلۡكَعۡبَيۡنِۚ وَإِن كُنتُمۡ جُنُبࣰ ا فَٱطَّهَّرُواْۚ وَإِن كُنتُم مَّرۡضَىٰٓ أَوۡ عَلَىٰ سَفَرٍ أَوۡ جَآءَ أَحَدࣱ مِّنكُم مِّنَ ٱلۡغَآئِطِ أَوۡ لَٰمَسۡتُمُ ٱلنِّسَآءَ فَلَمۡ تَجِدُواْ مَآءࣰ فَتَيَمَّمُواْ صَعِيدࣰ ا طَيِّبࣰ ا فَٱمۡسَحُواْ بِوُجُوهِكُمۡ وَأَيۡدِيكُم مِّنۡهُۚ مَا يُرِيدُ ٱللَّهُ لِيَجۡعَلَ عَلَيۡكُم مِّنۡ حَرَجࣲ وَلَٰكِن يُرِيدُ لِيُطَهِّرَكُمۡ وَلِيُتِمَّ نِعۡمَتَهُۥ عَلَيۡكُمۡ لَعَلَّكُمۡ تَشۡكُرُونَ','مومنو! جب تم نماز پڑھنے کا قصد کیا کرو تم منہ اور کہنیوں تک ہاتھ دھو لیا کرو اور سر کا مسح کر لیا کرو اور ٹخنوں تک پاؤں (دھو لیا کرو) اور اگر نہانے کی حاجت ہو تو (نہا کر) پاک ہو جایا کرو اور اگر بیمار ہو یا سفر میں ہو یا کوئی تم میں سے بیت الخلا سے ہو کر آیا ہو یا تم عورتوں سے ہم بستر ہوئے ہو اور تمہیں پانی نہ مل سکے تو پاک مٹی لو اور اس سے منہ اور ہاتھوں کا مسح (یعنی تیمم) کر لو۔ خدا تم پر کسی طرح کی تنگی نہیں کرنا چاہتا بلکہ یہ چاہتا ہے کہ تمہیں پاک کرے اور اپنی نعمتیں تم پر پوری کرے تاکہ تم شکر کرو','O believers! When you rise up for prayer, wash your faces and your hands up to the elbows, wipe your heads, and wash your feet to the ankles. And if you are in a state of ˹full˺ impurity, then take a full bath. But if you are ill, on a journey, or have relieved yourselves, or have been intimate with your wives and cannot find water, then purify yourselves with clean earth by wiping your faces and hands. It is not Allah’s Will to burden you, but to purify you and complete His favour upon you, so perhaps you will be grateful','ऐ ईमानदारों जब तुम नमाज़ के लिये आमादा हो तो अपने मुंह और कोहनियों तक हाथ धो लिया करो और अपने सरों का और टखनों तक पॉवों का मसाह कर लिया करो और अगर तुम हालते जनाबत में हो तो तुम तहारत (ग़ुस्ल) कर लो (हॉ) और अगर तुम बीमार हो या सफ़र में हो या तुममें से किसी को पैख़ाना निकल आए या औरतों से हमबिस्तरी की हो और तुमको पानी न मिल सके तो पाक ख़ाक से तैमूम कर लो यानि (दोनों हाथ मारकर) उससे अपने मुंह और अपने हाथों का मसा कर लो (देखो तो ख़ुदा ने कैसी आसानी कर दी) ख़ुदा तो ये चाहता ही नहीं कि तुम पर किसी तरह की तंगी करे बल्कि वो ये चाहता है कि पाक व पाकीज़ा कर दे और तुमपर अपनी नेअमते पूरी कर दे ताकि तुम शुक्रगुज़ार बन जाओ');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (5,7,'Al-Maaida','وَٱذۡكُرُواْ نِعۡمَةَ ٱللَّهِ عَلَيۡكُمۡ وَمِيثَٰقَهُ ٱلَّذِي وَاثَقَكُم بِهِۦٓ إِذۡ قُلۡتُمۡ سَمِعۡنَا وَأَطَعۡنَاۖ وَٱتَّقُواْ ٱللَّهَۚ إِنَّ ٱللَّهَ عَلِيمُۢ بِذَاتِ ٱلصُّدُورِ','اور خدا نے جو تم پر احسان کئے ہیں ان کو یاد کرو اور اس عہد کو بھی جس کا تم سے قول لیا تھا (یعنی) جب تم نے کہا تھا کہ ہم نے (خدا کا حکم) سن لیا اور قبول کیا۔ اور الله سے ڈرو۔ کچھ شک نہیں کہ خدا دلوں کی باتوں (تک) سے واقف ہے','Remember Allah’s favour upon you and the covenant He made with you when you said, “We hear and obey.” And be mindful of Allah. Surely Allah knows best what is ˹hidden˺ in the heart','और जो एहसानात ख़ुदा ने तुमपर किए हैं उनको और उस (एहद व पैमान) को याद करो जिसका तुमसे पक्का इक़रार ले चुका है जब तुमने कहा था कि हमने (एहकामे ख़ुदा को) सुना और दिल से मान लिया और ख़ुदा से डरते रहो क्योंकि इसमें ज़रा भी शक नहीं कि ख़ुदा दिलों के राज़ से भी बाख़बर है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (5,8,'Al-Maaida','يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ كُونُواْ قَوَّٰمِينَ لِلَّهِ شُهَدَآءَ بِٱلۡقِسۡطِۖ وَلَا يَجۡرِمَنَّكُمۡ شَنَـَٔانُ قَوۡمٍ عَلَىٰٓ أَلَّا تَعۡدِلُواْۚ ٱعۡدِلُواْ هُوَ أَقۡرَبُ لِلتَّقۡوَىٰۖ وَٱتَّقُواْ ٱللَّهَۚ إِنَّ ٱللَّهَ خَبِيرُۢ بِمَا تَعۡمَلُونَ','اے ایمان والوں! خدا کے لیے انصاف کی گواہی دینے کے لیے کھڑے ہو جایا کرو۔ اور لوگوں کی دشمنی تم کو اس بات پر آمادہ نہ کرے کہ انصاف چھوڑ دو۔ انصاف کیا کرو کہ یہی پرہیزگاری کی بات ہے اور خدا سے ڈرتے رہو۔ کچھ شک نہیں کہ خدا تمہارے سب اعمال سے خبردار ہے','O believers! Stand firm for Allah and bear true testimony. Do not let the hatred of a people lead you to injustice. Be just! That is closer to righteousness. And be mindful of Allah. Surely Allah is All-Aware of what you do','ऐ ईमानदारों ख़ुदा (की ख़ुशनूदी) के लिए इन्साफ़ के साथ गवाही देने के लिए तैयार रहो और तुम्हें किसी क़बीले की अदावत इस जुर्म में न फॅसवा दे कि तुम नाइन्साफी करने लगो (ख़बरदार बल्कि) तुम (हर हाल में) इन्साफ़ करो यही परहेज़गारी से बहुत क़रीब है और ख़ुदा से डरो क्योंकि जो कुछ तुम करते हो (अच्छा या बुरा) ख़ुदा उसे ज़रूर जानता है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (5,9,'Al-Maaida','وَعَدَ ٱللَّهُ ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ لَهُم مَّغۡفِرَةࣱ وَأَجۡرٌ عَظِيمࣱ‏','جو لوگ ایمان لائے اور نیک کام کرتے رہے ان سے خدا نے وعدہ فرمایا ہے کہ ان کے لیے بخشش اور اجر عظیم ہے','Allah has promised those who believe and do good ˹His˺ forgiveness and a great reward','और जिन लोगों ने ईमान क़ुबूल किया और अच्छे अच्छे काम किए ख़ुदा ने वायदा किया है कि उनके लिए (आख़िरत में) मग़फेरत और बड़ा सवाब है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (5,10,'Al-Maaida','وَٱلَّذِينَ كَفَرُواْ وَكَذَّبُواْ بِـَٔايَٰتِنَآ أُوْلَٰٓئِكَ أَصۡحَٰبُ ٱلۡجَحِيمِ','اور جنہوں نے کفر کیا اور ہماری آیتوں کو جھٹلایا وہ جہنمی ہیں','As for those who disbelieve and deny Our signs, they are the residents of the Hellfire','और जिन लोगों ने कुफ़्र इख्तेयार किया और हमारी आयतों को झुठलाया वह जहन्नुमी हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (5,11,'Al-Maaida','يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ ٱذۡكُرُواْ نِعۡمَتَ ٱللَّهِ عَلَيۡكُمۡ إِذۡ هَمَّ قَوۡمٌ أَن يَبۡسُطُوٓاْ إِلَيۡكُمۡ أَيۡدِيَهُمۡ فَكَفَّ أَيۡدِيَهُمۡ عَنكُمۡۖ وَٱتَّقُواْ ٱللَّهَۚ وَعَلَى ٱللَّهِ فَلۡيَتَوَكَّلِ ٱلۡمُؤۡمِنُونَ','اے ایمان والو! خدا نے جو تم پر احسان کیا ہے اس کو یاد کرو۔ جب ایک جماعت نے ارادہ کیا کہ تم پر دست درازی کریں تو اس نے ان کے ہاتھ روک دیئے اور خدا سے ڈرتے رہوں اور مومنو کو خدا ہی پر بھروسہ رکھنا چاہیئے','O believers! Remember Allah’s favour upon you: when a people sought to harm you, but He held their hands back from you. Be mindful of Allah. And in Allah let the believers put their trust','ऐ ईमानदारों ख़ुदा ने जो एहसानात तुमपर किए हैं उनको याद करो और ख़ूसूसन जब एक क़बीले ने तुम पर दस्त दराज़ी का इरादा किया था तो ख़ुदा ने उनके हाथों को तुम तक पहुंचने से रोक दिया और ख़ुदा से डरते रहो और मोमिनीन को ख़ुदा ही पर भरोसा रखना चाहिए');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (5,12,'Al-Maaida','۞وَلَقَدۡ أَخَذَ ٱللَّهُ مِيثَٰقَ بَنِيٓ إِسۡرَٰٓءِيلَ وَبَعَثۡنَا مِنۡهُمُ ٱثۡنَيۡ عَشَرَ نَقِيبࣰ اۖ وَقَالَ ٱللَّهُ إِنِّي مَعَكُمۡۖ لَئِنۡ أَقَمۡتُمُ ٱلصَّلَوٰةَ وَءَاتَيۡتُمُ ٱلزَّكَوٰةَ وَءَامَنتُم بِرُسُلِي وَعَزَّرۡتُمُوهُمۡ وَأَقۡرَضۡتُمُ ٱللَّهَ قَرۡضًا حَسَنࣰ ا لَّأُكَفِّرَنَّ عَنكُمۡ سَيِّـَٔاتِكُمۡ وَلَأُدۡخِلَنَّكُمۡ جَنَّٰتࣲ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُۚ فَمَن كَفَرَ بَعۡدَ ذَٰلِكَ مِنكُمۡ فَقَدۡ ضَلَّ سَوَآءَ ٱلسَّبِيلِ','اور خدا نے بنی اسرائیل سے اقرار لیا اور ان میں ہم نے بارہ سردار مقرر کئے پھر خدا نے فرمایا کہ میں تمہارے ساتھ ہوں اگر تم نماز پڑھتے اور زکوٰة دیتے رہو گے اور میرے پیغمبروں پر ایمان لاؤ گے اور ان کی مدد کرو گے اور خدا کو قرض حسنہ دو گے تو میں تم سے تمہارے گناہ دور کر دوں گا اور تم کو بہشتوں میں داخل کروں گا جن کے نیچے نہریں بہہ رہی ہیں پھر جس نے اس کے بعد تم میں سے کفر کیا وہ سیدھے رستے سے بھٹک گیا','Allah made a covenant with the Children of Israel and appointed twelve leaders from among them and ˹then˺ said, “I am truly with you. If you establish prayer, pay alms-tax, believe in My messengers, support them, and lend to Allah a good loan, I will certainly forgive your sins and admit you into Gardens under which rivers flow. And whoever among you disbelieves afterwards has truly strayed from the Right Way.”','और इसमें भी शक नहीं कि ख़ुदा ने बनी इसराईल से (भी ईमान का) एहद व पैमान ले लिया था और हम (ख़ुदा) ने इनमें के बारह सरदार उनपर मुक़र्रर किए और ख़ुदा ने बनी इसराईल से फ़रमाया था कि मैं तो यक़ीनन तुम्हारे साथ हूं अगर तुम भी पाबन्दी से नमाज़ पढ़ते और ज़कात देते रहो और हमारे पैग़म्बरों पर ईमान लाओ और उनकी मदद करते रहो और ख़ुदा (की ख़ुशनूदी के वास्ते लोगों को) क़र्जे हसना देते रहो तो मैं भी तुम्हारे गुनाह तुमसे ज़रूर दूर करूंगा और तुमको बेहिश्त के उन (हरे भरे ) बाग़ों में जा पहुंचाऊॅगा जिनके (दरख्तों के) नीचे नहरें जारी हैं फिर तुममें से जो शख्स इसके बाद भी इन्कार करे तो यक़ीनन वह राहे रास्त से भटक गया');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (5,13,'Al-Maaida','فَبِمَا نَقۡضِهِم مِّيثَٰقَهُمۡ لَعَنَّٰهُمۡ وَجَعَلۡنَا قُلُوبَهُمۡ قَٰسِيَةࣰۖ يُحَرِّفُونَ ٱلۡكَلِمَ عَن مَّوَاضِعِهِۦ وَنَسُواْ حَظࣰّ ا مِّمَّا ذُكِّرُواْ بِهِۦۚ وَلَا تَزَالُ تَطَّلِعُ عَلَىٰ خَآئِنَةࣲ مِّنۡهُمۡ إِلَّا قَلِيلࣰ ا مِّنۡهُمۡۖ فَٱعۡفُ عَنۡهُمۡ وَٱصۡفَحۡۚ إِنَّ ٱللَّهَ يُحِبُّ ٱلۡمُحۡسِنِينَ','تو ان لوگوں کے عہد توڑ دینے کے سبب ہم نے ان پر لعنت کی اور ان کے دلوں کو سخت کر دیا یہ لوگ کلمات (کتاب) کو اپنے مقامات سے بدل دیتے ہیں اور جن باتوں کی ان کو نصیحت کی گئی تھی ان کا بھی ایک حصہ فراموش کر بیٹھے اور تھوڑے آدمیوں کے سوا ہمیشہ تم ان کی (ایک نہ ایک) خیانت کی خبر پاتے رہتے ہو تو ان کی خطائیں معاف کردو اور (ان سے) درگزر کرو کہ خدا احسان کرنے والوں کو دوست رکھتا ہے','But for breaking their covenant We condemned them and hardened their hearts. They distorted the words of the Scripture and neglected a portion of what they had been commanded to uphold. You ˹O Prophet˺ will always find deceit on their part, except for a few. But pardon them and bear with them. Indeed, Allah loves the good-doers','पस हमने उनकीे एहद शिकनी की वजह से उनपर लानत की और उनके दिलों को (गोया) हमने ख़ुद सख्त बना दिया कि (हमारे) कलमात को उनके असली मायनों से बदल कर दूसरे मायनो में इस्तेमाल करते हैं और जिन जिन बातों की उन्हें नसीहत की गयी थी उनमें से एक बड़ा हिस्सा भुला बैठे और (ऐ रसूल) अब तो उनमें से चन्द आदमियों के सिवा एक न एक की ख्यानत पर बराबर मुत्तेला होते रहते हो तो तुम उन (के क़सूर) को माफ़ कर दो और (उनसे) दरगुज़र करो (क्योंकि) ख़ुदा एहसान करने वालों को ज़रूर दोस्त रखता है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (5,14,'Al-Maaida','وَمِنَ ٱلَّذِينَ قَالُوٓاْ إِنَّا نَصَٰرَىٰٓ أَخَذۡنَا مِيثَٰقَهُمۡ فَنَسُواْ حَظࣰّ ا مِّمَّا ذُكِّرُواْ بِهِۦ فَأَغۡرَيۡنَا بَيۡنَهُمُ ٱلۡعَدَاوَةَ وَٱلۡبَغۡضَآءَ إِلَىٰ يَوۡمِ ٱلۡقِيَٰمَةِۚ وَسَوۡفَ يُنَبِّئُهُمُ ٱللَّهُ بِمَا كَانُواْ يَصۡنَعُونَ','اور جو لوگ (اپنے تئیں) کہتے ہیں کہ ہم نصاریٰ ہیں ہم نے ان سے بھی عہد لیا تھا مگر انہوں نے بھی اس نصیحت کا جو ان کو کی گئی تھی ایک حصہ فراموش کر دیا تو ہم نے ان کے باہم قیامت تک کے لیے دشمنی اور کینہ ڈال دیا اور جو کچھ وہ کرتے رہے خدا عنقریب ان کو اس سے آگاہ کرے گا','And from those who say, “We are Christians,” We took their covenant, but they neglected a portion of what they had been commanded to uphold. So We let hostility and enmity arise between them until the Day of Judgment, and soon Allah will inform them of all they have done','और जो लोग कहते हैं कि हम नसरानी हैं उनसे (भी) हमने ईमान का एहद (व पैमान) लिया था मगर जब जिन जिन बातों की उन्हें नसीहत की गयी थी उनमें से एक बड़ा हिस्सा (रिसालत) भुला बैठे तो हमने भी (उसकी सज़ा में) क़यामत तक उनमें बाहम अदावत व दुशमनी की बुनियाद डाल दी और ख़ुदा उन्हें बहुत जल्द (क़यामत के दिन) बता देगा कि वह क्या क्या करते थे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (5,15,'Al-Maaida','يَٰٓأَهۡلَ ٱلۡكِتَٰبِ قَدۡ جَآءَكُمۡ رَسُولُنَا يُبَيِّنُ لَكُمۡ كَثِيرࣰ ا مِّمَّا كُنتُمۡ تُخۡفُونَ مِنَ ٱلۡكِتَٰبِ وَيَعۡفُواْ عَن كَثِيرࣲۚ قَدۡ جَآءَكُم مِّنَ ٱللَّهِ نُورࣱ وَكِتَٰبࣱ مُّبِينࣱ‏','اے اہل کتاب! تمہارے پاس ہمارے پیغمبر (آخرالزماں) آ گئے ہیں کہ جو کچھ تم کتاب (الہٰی) میں سے چھپاتے تھے وہ اس میں سے بہت کچھ تمہیں کھول کھول کر بتا دیتے ہیں اور تمہارے بہت سے قصور معاف کر دیتے ہیں بےشک تمہارے پاس خدا کی طرف سے نور اور روشن کتاب آ چکی ہے','O People of the Book! Now Our Messenger has come to you, revealing much of what you have hidden of the Scriptures and disregarding much. There certainly has come to you from Allah a light and a clear Book','ऐ अहले किताब तुम्हारे पास हमारा पैगम्बर (मोहम्मद सल्ल) आ चुका जो किताबे ख़ुदा की उन बातों में से जिन्हें तुम छुपाया करते थे बहुतेरी तो साफ़ साफ़ बयान कर देगा और बहुतेरी से (अमदन) दरगुज़र करेगा तुम्हरे पास तो ख़ुदा की तरफ़ से एक (चमकता हुआ) नूर और साफ़ साफ़ बयान करने वाली किताब (कुरान) आ चुकी है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (5,16,'Al-Maaida','يَهۡدِي بِهِ ٱللَّهُ مَنِ ٱتَّبَعَ رِضۡوَٰنَهُۥ سُبُلَ ٱلسَّلَٰمِ وَيُخۡرِجُهُم مِّنَ ٱلظُّلُمَٰتِ إِلَى ٱلنُّورِ بِإِذۡنِهِۦ وَيَهۡدِيهِمۡ إِلَىٰ صِرَٰطࣲ مُّسۡتَقِيمࣲ‏','جس سے خدا اپنی رضا پر چلنے والوں کو نجات کے رستے دکھاتا ہے اور اپنے حکم سے اندھیرے میں سے نکال کر روشنی کی طرف لے جاتا اور ان کو سیدھے رستہ پر چلاتا ہے','through which Allah guides those who seek His pleasure to the ways of peace, brings them out of darkness and into light by His Will, and guides them to the Straight Path','जो लोग ख़ुदा की ख़ुशनूदी के पाबन्द हैं उनको तो उसके ज़रिए से राहे निजात की हिदायत करता है और अपने हुक्म से (कुफ़्र की) तारीकी से निकालकर (ईमान की) रौशनी में लाता है और राहे रास्त पर पहुंचा देता है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (5,17,'Al-Maaida','لَّقَدۡ كَفَرَ ٱلَّذِينَ قَالُوٓاْ إِنَّ ٱللَّهَ هُوَ ٱلۡمَسِيحُ ٱبۡنُ مَرۡيَمَۚ قُلۡ فَمَن يَمۡلِكُ مِنَ ٱللَّهِ شَيۡـًٔا إِنۡ أَرَادَ أَن يُهۡلِكَ ٱلۡمَسِيحَ ٱبۡنَ مَرۡيَمَ وَأُمَّهُۥ وَمَن فِي ٱلۡأَرۡضِ جَمِيعࣰ اۗ وَلِلَّهِ مُلۡكُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَمَا بَيۡنَهُمَاۚ يَخۡلُقُ مَا يَشَآءُۚ وَٱللَّهُ عَلَىٰ كُلِّ شَيۡءࣲ قَدِيرࣱ‏','جو لوگ اس بات کے قائل ہیں کہ عیسیٰ بن مریم خدا ہیں وہ بےشک کافر ہیں (ان سے) کہہ دو کہ اگر خدا عیسیٰ بن مریم کو اور ان کی والدہ کو اور جتنے لوگ زمین میں ہیں سب کو ہلاک کرنا چاہے تو اس کے آگے کس کی پیش چل سکتی ہے؟ اور آسمان اور زمین اور جو کچھ ان دونوں میں ہے سب پر خدا ہی کی بادشاہی ہے وہ جو چاہتا ہے پیدا کرتا ہے اور خدا ہر چیز پر قادر ہے','Indeed, those who say, “Allah is the Messiah, son of Mary,” have fallen into disbelief. Say, ˹O Prophet,˺ “Who has the power to prevent Allah if He chose to destroy the Messiah, son of Mary, his mother, and everyone in the world all together?” To Allah ˹alone˺ belongs the kingdom of the heavens and the earth and everything in between. He creates whatever He wills. And Allah is Most Capable of everything','जो लोग उसके क़ायल हैं कि मरियम के बेटे मसीह बस ख़ुदा हैं वह ज़रूर काफ़िर हो गए (ऐ रसूल) उनसे पूंछो तो कि भला अगर ख़ुदा मरियम के बेटे मसीह और उनकी मॉ को और जितने लोग ज़मीन में हैं सबको मार डालना चाहे तो कौन ऐसा है जिसका ख़ुदा से भी ज़ोर चले (और रोक दे) और सारे आसमान और ज़मीन में और जो कुछ भी उनके दरमियान में है सब ख़ुदा ही की सल्तनत है जो चाहता है पैदा करता है और ख़ुदा तो हर चीज़ पर क़ादिर है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (5,18,'Al-Maaida','وَقَالَتِ ٱلۡيَهُودُ وَٱلنَّصَٰرَىٰ نَحۡنُ أَبۡنَٰٓؤُاْ ٱللَّهِ وَأَحِبَّٰٓؤُهُۥۚ قُلۡ فَلِمَ يُعَذِّبُكُم بِذُنُوبِكُمۖ بَلۡ أَنتُم بَشَرࣱ مِّمَّنۡ خَلَقَۚ يَغۡفِرُ لِمَن يَشَآءُ وَيُعَذِّبُ مَن يَشَآءُۚ وَلِلَّهِ مُلۡكُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَمَا بَيۡنَهُمَاۖ وَإِلَيۡهِ ٱلۡمَصِيرُ','اور یہود اور نصاریٰ کہتے ہیں کہ ہم خدا کے بیٹے اور اس کے پیارے ہیں کہو کہ پھر وہ تمہاری بداعمالیوں کے سبب تمھیں عذاب کیوں دیتا ہے (نہیں) بلکہ تم اس کی مخلوقات میں (دوسروں کی طرح کے) انسان ہو وہ جسے چاہے بخشے اور جسے چاہے عذاب دے اور آسمان زمین اور جو کچھ ان دونوں میں ہے سب پر خدا ہی کی حکومت ہے اور (سب کو) اسی کی طرف لوٹ کر جانا ہے','The Jews and the Christians each say, “We are the children of Allah and His most beloved!” Say, ˹O Prophet,˺ “Why then does He punish you for your sins? No! You are only humans like others of His Own making. He forgives whoever He wills and punishes whoever He wills. To Allah ˹alone˺ belongs the kingdom of the heavens and the earth and everything in between. And to Him is the final return.”','और नसरानी और यहूदी तो कहते हैं कि हम ही ख़ुदा के बेटे और उसके चहेते हैं (ऐ रसूल) उनसे तुम कह दो (कि अगर ऐसा है) तो फिर तुम्हें तुम्हारे गुनाहों की सज़ा क्यों देता है (तुम्हारा ख्याल लग़ो है) बल्कि तुम भी उसकी मख़लूक़ात से एक बशर हो ख़ुदा जिसे चाहेगा बख़ देगा और जिसको चाहेगा सज़ा देगा आसमान और ज़मीन और जो कुछ उन दोनों के दरमियान में है सब ख़ुदा ही का मुल्क है और सबको उसी की तरफ़ लौट कर जाना है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (5,19,'Al-Maaida','يَٰٓأَهۡلَ ٱلۡكِتَٰبِ قَدۡ جَآءَكُمۡ رَسُولُنَا يُبَيِّنُ لَكُمۡ عَلَىٰ فَتۡرَةࣲ مِّنَ ٱلرُّسُلِ أَن تَقُولُواْ مَا جَآءَنَا مِنۢ بَشِيرࣲ وَلَا نَذِيرࣲۖ فَقَدۡ جَآءَكُم بَشِيرࣱ وَنَذِيرࣱۗ وَٱللَّهُ عَلَىٰ كُلِّ شَيۡءࣲ قَدِيرࣱ‏','اے اہلِ کتاب پیغمبروں کے آنے کا سلسلہ جو (ایک عرصے تک) منقطع رہا تو (اب) تمہارے پاس ہمارے پیغمبر آ گئے ہیں جو تم سے (ہمارے احکام) بیان کرتے ہیں تاکہ تم یہ نہ کہو کہ ہمارے پاس کوئی خوشخبری یا ڈر سنانے والا نہیں آیا سو (اب) تمہارے پاس خوشخبری اور ڈر سنانے والے آ گئے ہیں اور خدا ہر چیز پر قادر ہے','O People of the Book! Our Messenger has indeed come to you, making things clear to you after an interval between the messengers so you do not say, “There has never come to us a deliverer of good news or a warner.” Now there has come to you a deliverer of good news and a warner. And Allah is Most Capable of everything','ऐ अहले किताब जब पैग़म्बरों की आमद में बहुत रूकावट हुई तो हमारा रसूल तुम्हारे पास आया जो एहकामे ख़ुदा को साफ़ साफ़ बयान करता है ताकि तुम कहीं ये न कह बैठो कि हमारे पास तो न कोई ख़ुशख़बरी देने वाला (पैग़म्बर) आया न (अज़ाब से) डराने वाला अब तो (ये नहीं कह सकते क्योंकि) यक़ीनन तुम्हारे पास ख़ुशख़बरी देने वाला और डराने वाला पैग़म्बर आ गया और ख़ुदा हर चीज़ पर क़ादिर है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (5,20,'Al-Maaida','وَإِذۡ قَالَ مُوسَىٰ لِقَوۡمِهِۦ يَٰقَوۡمِ ٱذۡكُرُواْ نِعۡمَةَ ٱللَّهِ عَلَيۡكُمۡ إِذۡ جَعَلَ فِيكُمۡ أَنۢبِيَآءَ وَجَعَلَكُم مُّلُوكࣰ ا وَءَاتَىٰكُم مَّا لَمۡ يُؤۡتِ أَحَدࣰ ا مِّنَ ٱلۡعَٰلَمِينَ','اور جب موسیٰ نے اپنی قوم سے کہا کہ بھائیو تم پر خدا نے جو احسان کئے ہیں ان کو یاد کرو کہ اس نے تم میں پیغمبر پیدا کیے اور تمہیں بادشاہ بنایا اور تم کو اتنا کچھ عنایت کیا کہ اہل عالم میں سے کسی کو نہیں دیا','And ˹remember˺ when Moses said to his people, “O my people! Remember Allah’s favours upon you when He raised prophets from among you, made you sovereign, and gave you what He had never given anyone in the world','ऐ रसूल उनको वह वक्त याद (दिलाओ) जब मूसा ने अपनी क़ौम से कहा था कि ऐ मेरी क़ौम जो नेअमते ख़ुदा ने तुमको दी है उसको याद करो इसलिए कि उसने तुम्हीं लोगों से बहुतेरे पैग़म्बर बनाए और तुम ही लोगों को बादशाह (भी) बनाया और तुम्हें वह नेअमतें दी हैं जो सारी ख़ुदायी में किसी एक को न दीं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (5,21,'Al-Maaida','يَٰقَوۡمِ ٱدۡخُلُواْ ٱلۡأَرۡضَ ٱلۡمُقَدَّسَةَ ٱلَّتِي كَتَبَ ٱللَّهُ لَكُمۡ وَلَا تَرۡتَدُّواْ عَلَىٰٓ أَدۡبَارِكُمۡ فَتَنقَلِبُواْ خَٰسِرِينَ','تو بھائیو! تم ارض مقدس (یعنی ملک شام) میں جسے خدا نے تمہارے لیے لکھ رکھا ہے چل داخل ہو اور (دیکھنا مقابلے کے وقت) پیٹھ نہ پھیر دینا ورنہ نقصان میں پڑ جاؤ گے','O my people! Enter the Holy Land which Allah has destined for you ˹to enter˺. And do not turn back or else you will become losers.”','ऐ मेरी क़ौम (शाम) की उस मुक़द्दस ज़मीन में जाओ जहॉ ख़ुदा ने तुम्हारी तक़दीर में (हुकूमत) लिख दी है और दुशमन के मुक़ाबले पीठ न फेरो (क्योंकि) इसमें तो तुम ख़ुद उलटा घाटा उठाओगे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (5,22,'Al-Maaida','قَالُواْ يَٰمُوسَىٰٓ إِنَّ فِيهَا قَوۡمࣰ ا جَبَّارِينَ وَإِنَّا لَن نَّدۡخُلَهَا حَتَّىٰ يَخۡرُجُواْ مِنۡهَا فَإِن يَخۡرُجُواْ مِنۡهَا فَإِنَّا دَٰخِلُونَ','وہ کہنے لگے کہ موسیٰ! وہاں تو بڑے زبردست لوگ (رہتے) ہیں اور جب تک وہ اس سرزمین سے نکل نہ جائیں ہم وہاں جا نہیں سکتے ہاں اگر وہ وہاں سے نکل جائیں تو ہم جا داخل ہوں گے','They replied, “O Moses! There is an enormously powerful people there, so we will never ˹be able to˺ enter it until they leave. If they do, then we will enter!”','वह लोग कहने लगे कि ऐ मूसा इस मुल्क में तो बड़े ज़बरदस्त (सरकश) लोग रहते हैं और जब तक वह लोग इसमें से निकल न जाएं हम तो उसमें कभी पॉव भी न रखेंगे हॉ अगर वह लोग ख़ुद इसमें से निकल जाएं तो अलबत्ता हम ज़रूर जाएंगे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (5,23,'Al-Maaida','قَالَ رَجُلَانِ مِنَ ٱلَّذِينَ يَخَافُونَ أَنۡعَمَ ٱللَّهُ عَلَيۡهِمَا ٱدۡخُلُواْ عَلَيۡهِمُ ٱلۡبَابَ فَإِذَا دَخَلۡتُمُوهُ فَإِنَّكُمۡ غَٰلِبُونَۚ وَعَلَى ٱللَّهِ فَتَوَكَّلُوٓاْ إِن كُنتُم مُّؤۡمِنِينَ','جو لوگ (خدا سے) ڈرتے تھے ان میں سے دو شخص جن پر خدا کی عنایت تھی کہنے لگے کہ ان لوگوں پر دروازے کے رستے سے حملہ کردو جب تم دروازے میں داخل ہو گئے تو فتح تمہارے ہے اور خدا ہی پر بھروسہ رکھو بشرطیکہ صاحبِ ایمان ہو','Two God-fearing men—who had been blessed by Allah—said, “Surprise them through the gate. If you do, you will certainly prevail. Put your trust in Allah if you are ˹truly˺ believers.”','(मगर) वह आदमी (यूशा कालिब) जो ख़ुदा का ख़ौफ़ रखते थे और जिनपर ख़ुदा ने ख़ास अपना फ़ज़ल (करम) किया था बेधड़क बोल उठे कि (अरे) उनपर हमला करके (बैतुल मुक़दस के फाटक में तो घुस पड़ो फिर देखो तो यह ऐसे बोदे हैं कि) इधर तुम फाटक में घुसे और (ये सब भाग खड़े हुए और) तुम्हारी जीत हो गयी और अगर सच्चे ईमानदार हो तो ख़ुदा ही पर भरोसा रखो');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (5,24,'Al-Maaida','قَالُواْ يَٰمُوسَىٰٓ إِنَّا لَن نَّدۡخُلَهَآ أَبَدࣰ ا مَّا دَامُواْ فِيهَا فَٱذۡهَبۡ أَنتَ وَرَبُّكَ فَقَٰتِلَآ إِنَّا هَٰهُنَا قَٰعِدُونَ','وہ بولے کہ موسیٰ! جب تک وہ لوگ وہاں ہیں ہم کبھی وہاں نہیں جا سکتے (اگر لڑنا ہی ضرور ہے) تو تم اور تمہارا خدا جاؤ اور لڑو ہم یہیں بیٹھے رہیں گے','˹Yet˺ they said, “O Moses! ˹Still˺ we will never enter as long as they remain there. So go—both you and your Lord—and fight; we are staying right here!”','वह कहने लगे एक मूसा (चाहे जो कुछ हो) जब तक वह लोग इसमें हैं हम तो उसमें हरगिज़ (लाख बरस) पॉव न रखेंगे हॉ तुम जाओ और तुम्हारा ख़ुदा जाए ओर दोनों (जाकर) लड़ो हम तो यहीं जमे बैठे हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (5,25,'Al-Maaida','قَالَ رَبِّ إِنِّي لَآ أَمۡلِكُ إِلَّا نَفۡسِي وَأَخِيۖ فَٱفۡرُقۡ بَيۡنَنَا وَبَيۡنَ ٱلۡقَوۡمِ ٱلۡفَٰسِقِينَ','موسیٰ نے (خدا سے) التجا کی کہ پروردگار میں اپنے اور اپنے بھائی کے سوا اور کسی پر اختیار نہیں رکھتا تو ہم میں اور ان نافرمان لوگوں میں جدائی کردے','Moses pleaded, “My Lord! I have no control over anyone except myself and my brother. So set us apart from the rebellious people.”','तब मूसा ने अर्ज़ की ख़ुदावन्दा तू ख़ूब वाक़िफ़ है कि अपनी ज़ाते ख़ास और अपने भाई के सिवा किसी पर मेरा क़ाबू नहीं बस अब हमारे और उन नाफ़रमान लोगों के दरमियान जुदाई डाल दे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (5,26,'Al-Maaida','قَالَ فَإِنَّهَا مُحَرَّمَةٌ عَلَيۡهِمۡۛ أَرۡبَعِينَ سَنَةࣰۛ يَتِيهُونَ فِي ٱلۡأَرۡضِۚ فَلَا تَأۡسَ عَلَى ٱلۡقَوۡمِ ٱلۡفَٰسِقِينَ','خدا نے فرمایا کہ وہ ملک ان پر چالیس برس تک کے لیے حرام کر دیا گیا (کہ وہاں جانے نہ پائیں گے اور جنگل کی) زمین میں سرگرداں پھرتے رہیں گے تو ان نافرمان لوگوں کے حال پر افسوس نہ کرو','Allah replied, “Then this land is forbidden to them for forty years, during which they will wander through the land. So do not grieve for the rebellious people.”','हमारा उनका साथ नहीं हो सकता (ख़ुदा ने फ़रमाया) (अच्छा) तो उनकी सज़ा यह है कि उनको चालीस बरस तक की हुकूमत नसीब न होगा (और उस मुद्दते दराज़ तक) यह लोग (मिस्र के) जंगल में सरगरदॉ रहेंगे तो फिर तुम इन बदचलन बन्दों पर अफ़सोस न करना');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (5,27,'Al-Maaida','۞وَٱتۡلُ عَلَيۡهِمۡ نَبَأَ ٱبۡنَيۡ ءَادَمَ بِٱلۡحَقِّ إِذۡ قَرَّبَا قُرۡبَانࣰ ا فَتُقُبِّلَ مِنۡ أَحَدِهِمَا وَلَمۡ يُتَقَبَّلۡ مِنَ ٱلۡأٓخَرِ قَالَ لَأَقۡتُلَنَّكَۖ قَالَ إِنَّمَا يَتَقَبَّلُ ٱللَّهُ مِنَ ٱلۡمُتَّقِينَ','اور (اے محمد) ان کو آدم کے دو بیٹوں (ہابیل اور قابیل) کے حالات (جو بالکل) سچے (ہیں) پڑھ کر سنا دو کہ جب ان دونوں نے خدا (کی جناب میں) کچھ نیازیں چڑھائیں تو ایک کی نیاز تو قبول ہو گئی اور دوسرے کی قبول نہ ہوئی (تب قابیل ہابیل سے) کہنے لگا کہ میں تجھے قتل کروں گا اس نے کہا کہ خدا پرہیزگاروں ہی کی (نیاز) قبول فرمایا کرتا ہے','Relate to them in truth ˹O Prophet˺ the story of Adam’s two sons—how each offered a sacrifice: Abel’s offering was accepted while Cain’s was not. So Cain threatened, “I will kill you!” His brother replied, “Allah only accepts ˹the offering˺ of the sincerely devout','(ऐ रसूल) तुम इन लोगों से आदम के दो बेटों (हाबील, क़ाबील) का सच्चा क़स्द बयान कर दो कि जब उन दोनों ने ख़ुदा की दरगाह में नियाज़ें चढ़ाई तो (उनमें से) एक (हाबील) की (नज़र तो) क़ुबूल हुई और दूसरे (क़ाबील) की नज़र न क़ुबूल हुई तो (मारे हसद के) हाबील से कहने लगा मैं तो तुझे ज़रूर मार डालूंगा उसने जवाब दिया कि (भाई इसमें अपना क्या बस है) ख़ुदा तो सिर्फ परहेज़गारों की नज़र कुबूल करता है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (5,28,'Al-Maaida','لَئِنۢ بَسَطتَ إِلَيَّ يَدَكَ لِتَقۡتُلَنِي مَآ أَنَا۠ بِبَاسِطࣲ يَدِيَ إِلَيۡكَ لِأَقۡتُلَكَۖ إِنِّيٓ أَخَافُ ٱللَّهَ رَبَّ ٱلۡعَٰلَمِينَ','اور اگر تو مجھے قتل کرنے کے لیے مجھ پر ہاتھ چلائے گا تو میں تجھ کو قتل کرنے کے لئے تجھ پر ہاتھ نہیں چلاؤں گا مجھے تو خدائے رب العالمین سے ڈر لگتا ہے','If you raise your hand to kill me, I will not raise mine to kill you, because I fear Allah—the Lord of all worlds','अगर तुम मेरे क़त्ल के इरादे से मेरी तरफ़ अपना हाथ बढ़ाओगे (तो ख़ैर बढ़ाओ) (मगर) मैं तो तुम्हारे क़त्ल के ख्याल से अपना हाथ बढ़ाने वाला नहीं (क्योंकि) मैं तो उस ख़ुदा से जो सारे जहॉन का पालने वाला है ज़रूर डरता हूं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (5,29,'Al-Maaida','إِنِّيٓ أُرِيدُ أَن تَبُوٓأَ بِإِثۡمِي وَإِثۡمِكَ فَتَكُونَ مِنۡ أَصۡحَٰبِ ٱلنَّارِۚ وَذَٰلِكَ جَزَٰٓؤُاْ ٱلظَّٰلِمِينَ','میں چاہتا ہوں کہ تو میرے گناہ میں بھی ماخوذ ہو اور اپنے گناہ میں بھی پھر (زمرہ) اہل دوزخ میں ہو اور ظالموں کی یہی سزا ہے','I want to let you bear your sin against me along with your other sins, then you will be one of those destined to the Fire. And that is the reward of the wrongdoers.”','मैं तो ज़रूर ये चाहता हूं कि मेरे गुनाह और तेरे गुनाह दोनों तेरे सर हो जॉए तो तू (अच्छा ख़ासा) जहन्नुमी बन जाए और ज़ालिमों की तो यही सज़ा है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (5,30,'Al-Maaida','فَطَوَّعَتۡ لَهُۥ نَفۡسُهُۥ قَتۡلَ أَخِيهِ فَقَتَلَهُۥ فَأَصۡبَحَ مِنَ ٱلۡخَٰسِرِينَ','مگر اس کے نفس نے اس کو بھائی کے قتل ہی کی ترغیب دی تو اس نے اسے قتل کر دیا اور خسارہ اٹھانے والوں میں ہو گیا','Yet Cain convinced himself to kill his brother, so he killed him—becoming a loser','फिर तो उसके नफ्स ने अपने भाई के क़त्ल पर उसे भड़का ही दिया आख़िर उस (कम्बख्त ने) उसको मार ही डाला तो घाटा उठाने वालों में से हो गया');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (5,31,'Al-Maaida','فَبَعَثَ ٱللَّهُ غُرَابࣰ ا يَبۡحَثُ فِي ٱلۡأَرۡضِ لِيُرِيَهُۥ كَيۡفَ يُوَٰرِي سَوۡءَةَ أَخِيهِۚ قَالَ يَٰوَيۡلَتَىٰٓ أَعَجَزۡتُ أَنۡ أَكُونَ مِثۡلَ هَٰذَا ٱلۡغُرَابِ فَأُوَٰرِيَ سَوۡءَةَ أَخِيۖ فَأَصۡبَحَ مِنَ ٱلنَّٰدِمِينَ','اب خدا نے ایک کوّا بھیجا جو زمین کریدنے لگا تاکہ اسے دکھائے کہ اپنے بھائی کی لاش کو کیونکر چھپائے کہنے لگا اے ہے مجھ سے اتنا بھی نہ ہو سکا کہ اس کوے کے برابر ہوتا کہ اپنے بھائی کی لاش چھپا دیتا پھر وہ پشیمان ہوا','Then Allah sent a crow digging ˹a grave˺ in the ground ˹for a dead crow˺, in order to show him how to bury the corpse of his brother. He cried, “Alas! Have I ˹even˺ failed to be like this crow and bury the corpse of my brother?” So he became regretful','(तब उसे फ़िक्र हुई कि लाश को क्या करे) तो ख़ुदा ने एक कौवे को भेजा कि वह ज़मीन को कुरेदने लगा ताकि उसे (क़ाबील) को दिखा दे कि उसे अपने भाई की लाश क्योंकर छुपानी चाहिए (ये देखकर) वह कहने लगा हाए अफ़सोस क्या मैं उस से भी आजिज़ हूं कि उस कौवे की बराबरी कर सकॅू कि (बला से यह भी होता) तो अपने भाई की लाश छुपा देता अलगरज़ वह (अपनी हरकत से) बहुत पछताया');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (5,32,'Al-Maaida','مِنۡ أَجۡلِ ذَٰلِكَ كَتَبۡنَا عَلَىٰ بَنِيٓ إِسۡرَٰٓءِيلَ أَنَّهُۥ مَن قَتَلَ نَفۡسَۢا بِغَيۡرِ نَفۡسٍ أَوۡ فَسَادࣲ فِي ٱلۡأَرۡضِ فَكَأَنَّمَا قَتَلَ ٱلنَّاسَ جَمِيعࣰ ا وَمَنۡ أَحۡيَاهَا فَكَأَنَّمَآ أَحۡيَا ٱلنَّاسَ جَمِيعࣰ اۚ وَلَقَدۡ جَآءَتۡهُمۡ رُسُلُنَا بِٱلۡبَيِّنَٰتِ ثُمَّ إِنَّ كَثِيرࣰ ا مِّنۡهُم بَعۡدَ ذَٰلِكَ فِي ٱلۡأَرۡضِ لَمُسۡرِفُونَ','اس قتل کی وجہ سے ہم نے بنی اسرائیل پر یہ حکم نازل کیا کہ جو شخص کسی کو (ناحق) قتل کرے گا (یعنی) بغیر اس کے کہ جان کا بدلہ لیا جائے یا ملک میں خرابی کرنے کی سزا دی جائے اُس نے گویا تمام لوگوں کو قتل کیا اور جو اس کی زندگانی کا موجب ہوا تو گویا تمام لوگوں کی زندگانی کا موجب ہوا اور ان لوگوں کے پاس ہمارے پیغمبر روشن دلیلیں لا چکے ہیں پھر اس کے بعد بھی ان سے بہت سے لوگ ملک میں حدِ اعتدال سے نکل جاتے ہیں','That is why We ordained for the Children of Israel that whoever takes a life—unless as a punishment for murder or mischief in the land—it will be as if they killed all of humanity; and whoever saves a life, it will be as if they saved all of humanity. ˹Although˺ Our messengers already came to them with clear proofs, many of them still transgressed afterwards through the land','इसी सबब से तो हमने बनी इसराईल पर वाजिब कर दिया था कि जो शख्स किसी को न जान के बदले में और न मुल्क में फ़साद फैलाने की सज़ा में (बल्कि नाहक़) क़त्ल कर डालेगा तो गोया उसने सब लोगों को क़त्ल कर डाला और जिसने एक आदमी को जिला दिया तो गोया उसने सब लोगों को जिला लिया और उन (बनी इसराईल) के पास तो हमारे पैग़म्बर (कैसे कैसे) रौशन मौजिज़े लेकर आ चुके हैं (मगर) फिर उसके बाद भी यक़ीनन उसमें से बहुतेरे ज़मीन पर ज्यादतियॉ करते रहे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (5,33,'Al-Maaida','إِنَّمَا جَزَٰٓؤُاْ ٱلَّذِينَ يُحَارِبُونَ ٱللَّهَ وَرَسُولَهُۥ وَيَسۡعَوۡنَ فِي ٱلۡأَرۡضِ فَسَادًا أَن يُقَتَّلُوٓاْ أَوۡ يُصَلَّبُوٓاْ أَوۡ تُقَطَّعَ أَيۡدِيهِمۡ وَأَرۡجُلُهُم مِّنۡ خِلَٰفٍ أَوۡ يُنفَوۡاْ مِنَ ٱلۡأَرۡضِۚ ذَٰلِكَ لَهُمۡ خِزۡيࣱ فِي ٱلدُّنۡيَاۖ وَلَهُمۡ فِي ٱلۡأٓخِرَةِ عَذَابٌ عَظِيمٌ','جو لوگ خدا اور اس کے رسول سے لڑائی کریں اور ملک میں فساد کرنے کو دوڑتے پھریں ان کی یہی سزا ہے کہ قتل کر دیئے جائیں یا سولی چڑھا دیئے جائیں یا ان کے ایک ایک طرف کے ہاتھ اور ایک ایک طرف کے پاؤں کاٹ دیئے جائیں یا ملک سے نکال دیئے جائیں یہ تو دنیا میں ان کی رسوائی ہے اور آخرت میں ان کے لیے بڑا (بھاری) عذاب تیار ہے','Indeed, the penalty for those who wage war against Allah and His Messenger and spread mischief in the land is death, crucifixion, cutting off their hands and feet on opposite sides, or exile from the land. This ˹penalty˺ is a disgrace for them in this world, and they will suffer a tremendous punishment in the Hereafter','जो लोग ख़ुदा और उसके रसूल से लड़ते भिड़ते हैं (और एहकाम को नहीं मानते) और फ़साद फैलाने की ग़रज़ से मुल्को (मुल्को) दौड़ते फिरते हैं उनकी सज़ा बस यही है कि (चुन चुनकर) या तो मार डाले जाएं या उन्हें सूली दे दी जाए या उनके हाथ पॉव हेर फेर कर एक तरफ़ का हाथ दूसरी तरफ़ का पॉव काट डाले जाएं या उन्हें (अपने वतन की) सरज़मीन से शहर बदर कर दिया जाए यह रूसवाई तो उनकी दुनिया में हुई और फिर आख़ेरत में तो उनके लिए बहुत बड़ा अज़ाब ही है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (5,34,'Al-Maaida','إِلَّا ٱلَّذِينَ تَابُواْ مِن قَبۡلِ أَن تَقۡدِرُواْ عَلَيۡهِمۡۖ فَٱعۡلَمُوٓاْ أَنَّ ٱللَّهَ غَفُورࣱ رَّحِيمࣱ‏','ہاں جن لوگوں نے اس سے پیشتر کہ تمہارے قابو میں آ جائیں توبہ کر لی تو جان رکھو کہ خدا بخشنے والا مہربان ہے','As for those who repent before you seize them, then know that Allah is All-Forgiving, Most Merciful','मगर (हॉ) जिन लोगों ने इससे पहले कि तुम इनपर क़ाबू पाओ तौबा कर लो तो उनका गुनाह बख्श दिया जाएगा क्योंकि समझ लो कि ख़ुदा बेशक बड़ा बख्शने वाला मेहरबान है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (5,35,'Al-Maaida','يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ ٱتَّقُواْ ٱللَّهَ وَٱبۡتَغُوٓاْ إِلَيۡهِ ٱلۡوَسِيلَةَ وَجَٰهِدُواْ فِي سَبِيلِهِۦ لَعَلَّكُمۡ تُفۡلِحُونَ','اے ایمان والو! خدا سے ڈرتے رہو اور اس کا قرب حاصل کرنے کا ذریعہ تلاش کرتے رہو اور اس کے رستے میں جہاد کرو تاکہ رستگاری پاؤ','O believers! Be mindful of Allah and seek what brings you closer to Him and struggle in His Way, so you may be successful','ऐ ईमानदारों ख़ुदा से डरते रहो और उसके (तक़र्रब (क़रीब होने) के) ज़रिये की जुस्तजू में रहो और उसकी राह में जेहाद करो ताकि तुम कामयाब हो जाओ');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (5,36,'Al-Maaida','إِنَّ ٱلَّذِينَ كَفَرُواْ لَوۡ أَنَّ لَهُم مَّا فِي ٱلۡأَرۡضِ جَمِيعࣰ ا وَمِثۡلَهُۥ مَعَهُۥ لِيَفۡتَدُواْ بِهِۦ مِنۡ عَذَابِ يَوۡمِ ٱلۡقِيَٰمَةِ مَا تُقُبِّلَ مِنۡهُمۡۖ وَلَهُمۡ عَذَابٌ أَلِيمࣱ‏','جو لوگ کافر ہیں اگر ان کے پاس روئے زمین (کے تمام خزانے اور اس) کا سب مال ومتاع ہو اور اس کے ساتھ اسی قدر اور بھی ہو تاکہ قیامت کے روز عذاب (سے رستگاری حاصل کرنے) کا بدلہ دیں تو ان سے قبول نہیں کیا جائے گا اور ان کو درد دینے والا عذاب ہوگا','As for the disbelievers, even if they were to possess everything in the world twice over ˹and offer it all˺ to ransom themselves from the punishment of the Day of Judgment, it would never be accepted from them. And they will suffer a painful punishment','इसमें शक नहीं कि जिन लोगों ने कुफ़्र इख्तेयार किया अगर उनके पास ज़मीन में जो कुछ (माल ख़ज़ाना) है (वह) सब बल्कि उतना और भी उसके साथ हो कि रोज़े क़यामत के अज़ाब का मुआवेज़ा दे दे (और ख़ुद बच जाए) तब भी (उसका ये मुआवेज़ा) कुबूल न किया जाएगा और उनके लिए दर्दनाक अज़ाब है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (5,37,'Al-Maaida','يُرِيدُونَ أَن يَخۡرُجُواْ مِنَ ٱلنَّارِ وَمَا هُم بِخَٰرِجِينَ مِنۡهَاۖ وَلَهُمۡ عَذَابࣱ مُّقِيمࣱ‏','(ہر چند) چاہیں گے کہ آگ سے نکل جائیں مگر اس سے نہیں نکل سکیں گے اور ان کے لئے ہمیشہ کا عذاب ہے','They will be desperate to get out of the Fire but they will never be able to. And they will suffer an everlasting punishment','वह लोग तो चाहेंगे कि किसी तरह जहन्नुम की आग से निकल भागे मगर वहॉ से तो वह निकल ही नहीं सकते और उनके लिए तो दाएमी अज़ाब है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (5,38,'Al-Maaida','وَٱلسَّارِقُ وَٱلسَّارِقَةُ فَٱقۡطَعُوٓاْ أَيۡدِيَهُمَا جَزَآءَۢ بِمَا كَسَبَا نَكَٰلࣰ ا مِّنَ ٱللَّهِۗ وَٱللَّهُ عَزِيزٌ حَكِيمࣱ‏','اور جو چوری کرے مرد ہو یا عورت ان کے ہاتھ کاٹ ڈالو یہ ان کے فعلوں کی سزا اور خدا کی طرف سے عبرت ہے اور خدا زبردست (اور) صاحب حکمت ہے','As for male and female thieves, cut off their hands for what they have done—a deterrent from Allah. And Allah is Almighty, All-Wise','और चोर ख्वाह मर्द हो या औरत तुम उनके करतूत की सज़ा में उनका (दाहिना) हाथ काट डालो ये (उनकी सज़ा) ख़ुदा की तरफ़ से है और ख़ुदा (तो) बड़ा ज़बरदस्त हिकमत वाला है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (5,39,'Al-Maaida','فَمَن تَابَ مِنۢ بَعۡدِ ظُلۡمِهِۦ وَأَصۡلَحَ فَإِنَّ ٱللَّهَ يَتُوبُ عَلَيۡهِۚ إِنَّ ٱللَّهَ غَفُورࣱ رَّحِيمٌ','اور جو شخص گناہ کے بعد توبہ کرے اور نیکوکار ہو جائے تو خدا اس کو معاف کر دے گا کچھ شک نہیں کہ خدا بخشنے والا مہربان ہے','But whoever repents after their wrongdoing and mends their ways, Allah will surely turn to them in forgiveness. Indeed, Allah is All-Forgiving, Most Merciful','हॉ जो अपने गुनाह के बाद तौबा कर ले और अपने चाल चलन दुरूस्त कर लें तो बेशक ख़ुदा भी तौबा कुबूल कर लेता है क्योंकि ख़ुदा तो बड़ा बख्शने वाला मेहरबान है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (5,40,'Al-Maaida','أَلَمۡ تَعۡلَمۡ أَنَّ ٱللَّهَ لَهُۥ مُلۡكُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ يُعَذِّبُ مَن يَشَآءُ وَيَغۡفِرُ لِمَن يَشَآءُۗ وَٱللَّهُ عَلَىٰ كُلِّ شَيۡءࣲ قَدِيرࣱ‏','کیا تم کو معلوم نہیں کہ آسمانوں اور زمین میں خدا ہی کی سلطنت ہے؟ جس کو چاہے عذاب کرے اور جسے چاہے بخش دے اور خدا ہر چیز پر قادر ہے','Do you not know that the kingdom of the heavens and the earth belongs to Allah ˹alone˺? He punishes whoever He wills and forgives whoever He wills. And Allah is Most Capable of everything','ऐ शख्स क्या तू नहीं जानता कि सारे आसमान व ज़मीन (ग़रज़ दुनिया जहान) में ख़ास ख़ुदा की हुकूमत है जिसे चाहे अज़ाब करे और जिसे चाहे माफ़ कर दे और ख़ुदा तो हर चीज़ पर क़ादिर है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (5,41,'Al-Maaida','۞يَٰٓأَيُّهَا ٱلرَّسُولُ لَا يَحۡزُنكَ ٱلَّذِينَ يُسَٰرِعُونَ فِي ٱلۡكُفۡرِ مِنَ ٱلَّذِينَ قَالُوٓاْ ءَامَنَّا بِأَفۡوَٰهِهِمۡ وَلَمۡ تُؤۡمِن قُلُوبُهُمۡۛ وَمِنَ ٱلَّذِينَ هَادُواْۛ سَمَّٰعُونَ لِلۡكَذِبِ سَمَّٰعُونَ لِقَوۡمٍ ءَاخَرِينَ لَمۡ يَأۡتُوكَۖ يُحَرِّفُونَ ٱلۡكَلِمَ مِنۢ بَعۡدِ مَوَاضِعِهِۦۖ يَقُولُونَ إِنۡ أُوتِيتُمۡ هَٰذَا فَخُذُوهُ وَإِن لَّمۡ تُؤۡتَوۡهُ فَٱحۡذَرُواْۚ وَمَن يُرِدِ ٱللَّهُ فِتۡنَتَهُۥ فَلَن تَمۡلِكَ لَهُۥ مِنَ ٱللَّهِ شَيۡـًٔاۚ أُوْلَٰٓئِكَ ٱلَّذِينَ لَمۡ يُرِدِ ٱللَّهُ أَن يُطَهِّرَ قُلُوبَهُمۡۚ لَهُمۡ فِي ٱلدُّنۡيَا خِزۡيࣱۖ وَلَهُمۡ فِي ٱلۡأٓخِرَةِ عَذَابٌ عَظِيمࣱ‏','اے پیغمبر! جو لوگ کفر میں جلدی کرتے ہیں (کچھ تو) ان میں سے (ہیں) جو منہ سے کہتے ہیں کہ ہم مومن ہیں لیکن ان کے دل مومن نہیں ہیں اور (کچھ) ان میں سے جو یہودی ہیں ان کی وجہ سے غمناک نہ ہونا یہ غلط باتیں بنانے کے لیے جاسوسی کرتے پھرتے ہیں اور ایسے لوگوں (کے بہکانے) کے لیے جاسوس بنے ہیں جو ابھی تمہارے پاس نہیں آئے (صحیح) باتوں کو ان کے مقامات (میں ثابت ہونے) کے بعد بدل دیتے ہیں (اور لوگوں سے) کہتے ہیں کہ اگر تم کو یہی (حکم) ملے تو اسے قبول کر لینا اور اگر یہ نہ ملے تو اس سے احتراز کرنا اور اگر کسی کو خدا گمراہ کرنا چاہے تو اس کے لیے تم کچھ بھی خدا سے (ہدایت کا) اختیار نہیں رکھتے یہ وہ لوگ ہیں جن کے دلوں کو خدا نے پاک کرنا نہیں چاہا ان کے لیے دنیا میں بھی ذلت ہے اور آخرت میں بھی بڑا عذاب ہے','O Messenger! Do not grieve for those who race to disbelieve—those who say, “We believe” with their tongues, but their hearts are in disbelief. Nor those among the Jews who eagerly listen to lies, attentive to those who are too arrogant to come to you. They distort the Scripture, taking rulings out of context, then say, “If this is the ruling you get ˹from Muḥammad˺, accept it. If not, beware!” Whoever Allah allows to be deluded, you can never be of any help to them against Allah. It is not Allah’s Will to purify their hearts. For them is disgrace in this world, and they will suffer a tremendous punishment in the Hereafter','ऐ रसूल जो लोग कुफ़्र की तरफ़ लपक के चले जाते हैं तुम उनका ग़म न खाओ उनमें बाज़ तो ऐसे हैं कि अपने मुंह से बे तकल्लुफ़ कह देते हैं कि हम ईमान लाए हालॉकि उनके दिल बेईमान हैं और बाज़ यहूदी ऐसे हैं कि (जासूसी की ग़रज़ से) झूठी बातें बहुत (शौक से) सुनते हैं ताकि कुफ्फ़ार के दूसरे गिरोह को जो (अभी तक) तुम्हारे पास नहीं आए हैं सुनाएं ये लोग (तौरैत के) अल्फ़ाज़ की उनके असली मायने (मालूम होने) के बाद भी तहरीफ़ करते हैं (और लोगों से) कहते हैं कि (ये तौरैत का हुक्म है) अगर मोहम्मद की तरफ़ से (भी) तुम्हें यही हुक्म दिया जाय तो उसे मान लेना और अगर यह हुक्म तुमको न दिया जाए तो उससे अलग ही रहना और (ऐ रसूल) जिसको ख़ुदा ख़राब करना चाहता है तो उसके वास्ते ख़ुदा से तुम्हारा कुछ ज़ोर नहीं चल सकता यह लोग तो वही हैं जिनके दिलों को ख़ुदा ने (गुनाहों से) पाक करने का इरादा ही नहीं किया (बल्कि) उनके लिए तो दुनिया में भी रूसवाई है और आख़ेरत में भी (उनके लिए) बड़ा (भारी) अज़ाब होगा');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (5,42,'Al-Maaida','سَمَّٰعُونَ لِلۡكَذِبِ أَكَّٰلُونَ لِلسُّحۡتِۚ فَإِن جَآءُوكَ فَٱحۡكُم بَيۡنَهُمۡ أَوۡ أَعۡرِضۡ عَنۡهُمۡۖ وَإِن تُعۡرِضۡ عَنۡهُمۡ فَلَن يَضُرُّوكَ شَيۡـࣰٔ اۖ وَإِنۡ حَكَمۡتَ فَٱحۡكُم بَيۡنَهُم بِٱلۡقِسۡطِۚ إِنَّ ٱللَّهَ يُحِبُّ ٱلۡمُقۡسِطِينَ','(یہ) جھوٹی باتیں بنانے کے جاسوسی کرنے والے اور (رشوت کا) حرام مال کھانے والے ہیں اگر یہ تمہارے پاس (کوئی مقدمہ فیصل کرانے کو) آئیں تو تم ان میں فیصلہ کر دینا یا اعراض کرنا اور اگر ان سے اعراض کرو گے تو وہ تمہارا کچھ بھی نہیں بگاڑ سکیں گے اور اگر فیصلہ کرنا چاہو تو انصاف کا فیصلہ کرنا کہ خدا انصاف کرنے والوں کو دوست رکھتا ہے','They eagerly listen to falsehood and consume forbidden gain. So if they come to you ˹O Prophet˺, either judge between them or turn away from them. If you turn away from them, they cannot harm you whatsoever. But if you judge between them, then do so with justice. Surely Allah loves those who are just','ये (कम्बख्त) झूठी बातों को बड़े शौक़ से सुनने वाले और बड़े ही हरामख़ोर हैं तो (ऐ रसूल) अगर ये लोग तुम्हारे पास (कोई मामला लेकर) आए तो तुमको इख्तेयार है ख्वाह उनके दरमियान फैसला कर दो या उनसे किनाराकशी करो और अगर तुम किनाराकश रहोगे तो (कुछ ख्याल न करो) ये लोग तुम्हारा हरगिज़ कुछ बिगाड़ नहीं सकते और अगर उनमें फैसला करो तो इन्साफ़ से फैसला करो क्योंकि ख़ुदा इन्साफ़ करने वालों को दोस्त रखता है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (5,43,'Al-Maaida','وَكَيۡفَ يُحَكِّمُونَكَ وَعِندَهُمُ ٱلتَّوۡرَىٰةُ فِيهَا حُكۡمُ ٱللَّهِ ثُمَّ يَتَوَلَّوۡنَ مِنۢ بَعۡدِ ذَٰلِكَۚ وَمَآ أُوْلَٰٓئِكَ بِٱلۡمُؤۡمِنِينَ','اور یہ تم سے (اپنے مقدمات) کیونکر فیصل کرایں گے جبکہ خود ان کے پاس تورات (موجود) ہے جس میں خدا کا حکم (لکھا ہوا) ہے (یہ اسے جانتے ہیں) پھر اس کے بعد اس سے پھر جاتے ہیں اور یہ لوگ ایمان ہی نہیں رکھتے','But why do they come to you for judgment when they ˹already˺ have the Torah containing Allah’s judgment, then they turn away after all? They are not ˹true˺ believers','और जब ख़ुद उनके पास तौरेत है और उसमें ख़ुदा का हुक्म (मौजूद) है तो फिर तुम्हारे पास फैसला कराने को क्यों आते हैं और (लुत्फ़ तो ये है कि) इसके बाद फिर (तुम्हारे हुक्म से) फिर जाते हैं ओर सच तो यह है कि यह लोग ईमानदार ही नहीं हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (5,44,'Al-Maaida','إِنَّآ أَنزَلۡنَا ٱلتَّوۡرَىٰةَ فِيهَا هُدࣰ ى وَنُورࣱۚ يَحۡكُمُ بِهَا ٱلنَّبِيُّونَ ٱلَّذِينَ أَسۡلَمُواْ لِلَّذِينَ هَادُواْ وَٱلرَّبَّٰنِيُّونَ وَٱلۡأَحۡبَارُ بِمَا ٱسۡتُحۡفِظُواْ مِن كِتَٰبِ ٱللَّهِ وَكَانُواْ عَلَيۡهِ شُهَدَآءَۚ فَلَا تَخۡشَوُاْ ٱلنَّاسَ وَٱخۡشَوۡنِ وَلَا تَشۡتَرُواْ بِـَٔايَٰتِي ثَمَنࣰ ا قَلِيلࣰ اۚ وَمَن لَّمۡ يَحۡكُم بِمَآ أَنزَلَ ٱللَّهُ فَأُوْلَٰٓئِكَ هُمُ ٱلۡكَٰفِرُونَ','بیشک ہم نے توریت نازل فرمائی جس میں ہدایت اور روشنی ہے اسی کے مطابق انبیاء جو (خدا کے) فرمانبردار تھے یہودیوں کو حکم دیتے رہے ہیں اور مشائخ اور علماء بھی کیونکہ وہ کتاب خدا کے نگہبان مقرر کیے گئے تھے اور اس پر گواہ تھے (یعنی حکم الہٰی کا یقین رکھتے تھے) تو تم لوگوں سے مت ڈرنا اور مجھی سے ڈرتے رہنا اور میری آیتوں کے بدلے تھوڑی سی قیمت نہ لینا اور جو خدا کے نازل فرمائے ہوئے احکام کے مطابق حکم نہ دے تو ایسے ہی لوگ کافر ہیں','Indeed, We revealed the Torah, containing guidance and light, by which the prophets, who submitted themselves to Allah, made judgments for Jews. So too did the rabbis and scholars judge according to Allah’s Book, with which they were entrusted and of which they were made keepers. So do not fear the people; fear Me! Nor trade my revelations for a fleeting gain. And those who do not judge by what Allah has revealed are ˹truly˺ the disbelievers','बेशक हम ने तौरेत नाज़िल की जिसमें (लोगों की) हिदायत और नूर (ईमान) है उसी के मुताबिक़ ख़ुदा के फ़रमाबरदार बन्दे (अम्बियाए बनी इसराईल) यहूदियों को हुक्म देते रहे और अल्लाह वाले और उलेमाए (यहूद) भी किताबे ख़ुदा से (हुक्म देते थे) जिसके वह मुहाफ़िज़ बनाए गए थे और वह उसके गवाह भी थे पस (ऐ मुसलमानों) तुम लोगों से (ज़रा भी) न डरो (बल्कि) मुझ ही से डरो और मेरी आयतों के बदले में (दुनिया की दौलत जो दर हक़ीक़त बहुत थोड़ी क़ीमत है) न लो और (समझ लो कि) जो शख्स ख़ुदा की नाज़िल की हुई (किताब) के मुताबिक़ हुक्म न दे तो ऐसे ही लोग काफ़िर हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (5,45,'Al-Maaida','وَكَتَبۡنَا عَلَيۡهِمۡ فِيهَآ أَنَّ ٱلنَّفۡسَ بِٱلنَّفۡسِ وَٱلۡعَيۡنَ بِٱلۡعَيۡنِ وَٱلۡأَنفَ بِٱلۡأَنفِ وَٱلۡأُذُنَ بِٱلۡأُذُنِ وَٱلسِّنَّ بِٱلسِّنِّ وَٱلۡجُرُوحَ قِصَاصࣱۚ فَمَن تَصَدَّقَ بِهِۦ فَهُوَ كَفَّارَةࣱ لَّهُۥۚ وَمَن لَّمۡ يَحۡكُم بِمَآ أَنزَلَ ٱللَّهُ فَأُوْلَٰٓئِكَ هُمُ ٱلظَّٰلِمُونَ','اور ہم نے ان لوگوں کے لیے تورات میں یہ حکم لکھ دیا تھا کہ جان کے بدلے جان اور آنکھ کے بدلے آنکھ اور ناک کے بدلے ناک اور کان کے بدلے کان اور دانت کے بدلے دانت اور سب زخموں کا اسی طرح بدلہ ہے لیکن جو شخص بدلہ معاف کر دے وہ اس کے لیے کفارہ ہوگا اور جو خدا کے نازل فرمائے ہوئے احکام کے مطابق حکم نہ دے تو ایسے ہی لوگ بےانصاف ہیں','We ordained for them in the Torah, “A life for a life, an eye for an eye, a nose for a nose, an ear for an ear, a tooth for a tooth—and for wounds equal retaliation.” But whoever waives it charitably, it will be atonement for them. And those who do not judge by what Allah has revealed are ˹truly˺ the wrongdoers','और हम ने तौरेत में यहूदियों पर यह हुक्म फर्ज क़र दिया था कि जान के बदले जान और ऑख के बदले ऑख और नाक के बदले नाक और कान के बदले कान और दॉत के बदले दॉत और जख्म के बदले (वैसा ही) बराबर का बदला (जख्म) है फिर जो (मज़लूम ज़ालिम की) ख़ता माफ़ कर दे तो ये उसके गुनाहों का कफ्फ़ारा हो जाएगा और जो शख्स ख़ुदा की नाज़िल की हुई (किताब) के मुवाफ़िक़ हुक्म न दे तो ऐसे ही लोग ज़ालिम हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (5,46,'Al-Maaida','وَقَفَّيۡنَا عَلَىٰٓ ءَاثَٰرِهِم بِعِيسَى ٱبۡنِ مَرۡيَمَ مُصَدِّقࣰ ا لِّمَا بَيۡنَ يَدَيۡهِ مِنَ ٱلتَّوۡرَىٰةِۖ وَءَاتَيۡنَٰهُ ٱلۡإِنجِيلَ فِيهِ هُدࣰ ى وَنُورࣱ وَمُصَدِّقࣰ ا لِّمَا بَيۡنَ يَدَيۡهِ مِنَ ٱلتَّوۡرَىٰةِ وَهُدࣰ ى وَمَوۡعِظَةࣰ لِّلۡمُتَّقِينَ','اور ان پیغمبروں کے بعد انہی کے قدموں پر ہم نے عیسیٰ بن مریم کو بھیجا جو اپنے سے پہلے کی کتاب تورات کی تصدیق کرتے تھے اور ان کو انجیل عنایت کی جس میں ہدایت اور نور ہے اور تورات کی جو اس سے پہلی کتاب (ہے) تصدیق کرتی ہے اور پرہیزگاروں کو راہ بتاتی اور نصیحت کرتی ہے','Then in the footsteps of the prophets, We sent Jesus, son of Mary, confirming the Torah revealed before him. And We gave him the Gospel containing guidance and light and confirming what was revealed in the Torah—a guide and a lesson to the God-fearing','और हम ने उन्हीं पैग़म्बरों के क़दम ब क़दम मरियम के बेटे ईसा को चलाया और वह इस किताब तौरैत की भी तस्दीक़ करते थे जो उनके सामने (पहले से) मौजूद थी और हमने उनको इन्जील (भी) अता की जिसमें (लोगों के लिए हर तरह की) हिदायत थी और नूर (ईमान) और वह इस किताब तौरेत की जो वक्ते नुज़ूले इन्जील (पहले से) मौजूद थी तसदीक़ करने वाली और परहेज़गारों की हिदायत व नसीहत थी');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (5,47,'Al-Maaida','وَلۡيَحۡكُمۡ أَهۡلُ ٱلۡإِنجِيلِ بِمَآ أَنزَلَ ٱللَّهُ فِيهِۚ وَمَن لَّمۡ يَحۡكُم بِمَآ أَنزَلَ ٱللَّهُ فَأُوْلَٰٓئِكَ هُمُ ٱلۡفَٰسِقُونَ','اور اہل انجیل کو چاہیئے کہ جو احکام خدا نے اس میں نازل فرمائے ہیں اس کے مطابق حکم دیا کریں اور جو خدا کے نازل کئے ہوئے احکام کے مطابق حکم نہ دے گا تو ایسے لوگ نافرماں ہیں','So let the people of the Gospel judge by what Allah has revealed in it. And those who do not judge by what Allah has revealed are ˹truly˺ the rebellious','और इन्जील वालों (नसारा) को जो कुछ ख़ुदा ने (उसमें) नाज़िल किया है उसके मुताबिक़ हुक्म करना चाहिए और जो शख्स ख़ुदा की नाज़िल की हुई (किताब के मुआफ़िक) हुक्म न दे तो ऐसे ही लोग बदकार हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (5,48,'Al-Maaida','وَأَنزَلۡنَآ إِلَيۡكَ ٱلۡكِتَٰبَ بِٱلۡحَقِّ مُصَدِّقࣰ ا لِّمَا بَيۡنَ يَدَيۡهِ مِنَ ٱلۡكِتَٰبِ وَمُهَيۡمِنًا عَلَيۡهِۖ فَٱحۡكُم بَيۡنَهُم بِمَآ أَنزَلَ ٱللَّهُۖ وَلَا تَتَّبِعۡ أَهۡوَآءَهُمۡ عَمَّا جَآءَكَ مِنَ ٱلۡحَقِّۚ لِكُلࣲّ جَعَلۡنَا مِنكُمۡ شِرۡعَةࣰ وَمِنۡهَاجࣰ اۚ وَلَوۡ شَآءَ ٱللَّهُ لَجَعَلَكُمۡ أُمَّةࣰ وَٰحِدَةࣰ وَلَٰكِن لِّيَبۡلُوَكُمۡ فِي مَآ ءَاتَىٰكُمۡۖ فَٱسۡتَبِقُواْ ٱلۡخَيۡرَٰتِۚ إِلَى ٱللَّهِ مَرۡجِعُكُمۡ جَمِيعࣰ ا فَيُنَبِّئُكُم بِمَا كُنتُمۡ فِيهِ تَخۡتَلِفُونَ','اور (اے پیغمبر!) ہم نے تم پر سچی کتاب نازل کی ہے جو اپنے سے پہلی کتابوں کی تصدیق کرتی ہے اور ان (سب) پر شامل ہے تو جو حکم خدا نے نازل فرمایا ہے اس کے مطابق ان کا فیصلہ کرنا اور حق جو تمہارے پاس آچکا ہے اس کو چھوڑ کر ان کی خواہشوں کی پیروی نہ کرنا ہم نے تم میں سے ہر ایک (فرقے) کے لیے ایک دستور اور طریقہ مقرر کیا ہے اور اگر خدا چاہتا تو سب کو ایک ہی شریعت پر کر دیتا مگر جو حکم اس نے تم کو دیئے ہیں ان میں وہ تمہاری آزمائش کرنی چاہتا ہے سو نیک کاموں میں جلدی کرو تم سب کو خدا کی طرف لوٹ کر جانا ہے پھر جن باتوں میں تم کو اختلاف تھا وہ تم کو بتا دے گا','We have revealed to you ˹O Prophet˺ this Book with the truth, as a confirmation of previous Scriptures and a supreme authority on them. So judge between them by what Allah has revealed, and do not follow their desires over the truth that has come to you. To each of you We have ordained a code of law and a way of life. If Allah had willed, He would have made you one community, but His Will is to test you with what He has given ˹each of˺ you. So compete with one another in doing good. To Allah you will all return, then He will inform you ˹of the truth˺ regarding your differences','और (ऐ रसूल) हमने तुम पर भी बरहक़ किताब नाज़िल की जो किताब (उसके पहले से) उसके वक्त में मौजूद है उसकी तसदीक़ करती है और उसकी निगेहबान (भी) है जो कुछ तुम पर ख़ुदा ने नाज़िल किया है उसी के मुताबिक़ तुम भी हुक्म दो और जो हक़ बात ख़ुदा की तरफ़ से आ चुकी है उससे कतरा के उन लोगों की ख्वाहिशे नफ़सियानी की पैरवी न करो और हमने तुम में हर एक के वास्ते (हस्बे मसलेहते वक्त) एक एक शरीयत और ख़ास तरीक़े पर मुक़र्रर कर दिया और अगर ख़ुदा चाहता तो तुम सब के सब को एक ही (शरीयत की) उम्मत बना देता मगर (मुख़तलिफ़ शरीयतों से) ख़ुदा का मतलब यह था कि जो कुछ तुम्हें दिया है उसमें तुम्हारा इमतेहान करे बस तुम नेकी में लपक कर आगे बढ़ जाओ और (यक़ीन जानो कि) तुम सब को ख़ुदा ही की तरफ़ लौट कर जाना है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (5,49,'Al-Maaida','وَأَنِ ٱحۡكُم بَيۡنَهُم بِمَآ أَنزَلَ ٱللَّهُ وَلَا تَتَّبِعۡ أَهۡوَآءَهُمۡ وَٱحۡذَرۡهُمۡ أَن يَفۡتِنُوكَ عَنۢ بَعۡضِ مَآ أَنزَلَ ٱللَّهُ إِلَيۡكَۖ فَإِن تَوَلَّوۡاْ فَٱعۡلَمۡ أَنَّمَا يُرِيدُ ٱللَّهُ أَن يُصِيبَهُم بِبَعۡضِ ذُنُوبِهِمۡۗ وَإِنَّ كَثِيرࣰ ا مِّنَ ٱلنَّاسِ لَفَٰسِقُونَ','اور (ہم پھر تاکید کرتے ہیں کہ) جو (حکم) خدا نے نازل فرمایا ہے اسی کے مطابق ان میں فیصلہ کرنا اور ان کی خواہشوں کی پیروی نہ کرنا اور ان سے بچتے رہنا کہ کسی حکم سے جو خدا نے تم پر نازل فرمایا ہے یہ کہیں تم کو بہکانہ دیں اگر یہ نہ مانیں تو جان لو کہ خدا چاہتا ہے کہ ان کے بعض گناہوں کے سبب ان پر مصیبت نازل کرے اور اکثر لوگ تو نافرمان ہیں','And judge between them ˹O Prophet˺ by what Allah has revealed, and do not follow their desires. And beware, so they do not lure you away from some of what Allah has revealed to you. If they turn away ˹from Allah’s judgment˺, then know that it is Allah’s Will to repay them for some of their sins, and that many people are indeed rebellious','तब (उस वक्त) ज़िन बातों में तुम इख्तेलाफ़ करते वह तुम्हें बता देगा और (ऐ रसूल) हम फिर कहते हैं कि जो एहकाम ख़ुदा नाज़िल किए हैं तुम उसके मुताबिक़ फैसला करो और उनकी (बेजा) ख्वाहिशे नफ़सियानी की पैरवी न करो (बल्कि) तुम उनसे बचे रहो (ऐसा न हो) कि किसी हुक्म से जो ख़ुदा ने तुम पर नाज़िल किया है तुमको ये लोग भटका दें फिर अगर ये लोग तुम्हारे हुक्म से मुंह मोड़ें तो समझ लो कि (गोया) ख़ुदा ही की मरज़ी है कि उनके बाज़ गुनाहों की वजह से उन्हें मुसीबत में फॅसा दे और इसमें तो शक ही नहीं कि बहुतेरे लोग बदचलन हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (5,50,'Al-Maaida','أَفَحُكۡمَ ٱلۡجَٰهِلِيَّةِ يَبۡغُونَۚ وَمَنۡ أَحۡسَنُ مِنَ ٱللَّهِ حُكۡمࣰ ا لِّقَوۡمࣲ يُوقِنُونَ','کیا یہ زمانہٴ جاہلیت کے حکم کے خواہش مند ہیں؟ اور جو یقین رکھتے ہیں ان کے لیے خدا سے اچھا حکم کس کا ہے؟','Is it the judgment of ˹pre-Islamic˺ ignorance they seek? Who could be a better judge than Allah for people of sure faith','क्या ये लोग (ज़मानाए) जाहिलीयत के हुक्म की (तुमसे भी) तमन्ना रखते हैं हालॉकि यक़ीन करने वाले लोगों के वास्ते हुक्मे ख़ुदा से बेहतर कौन होगा');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (5,51,'Al-Maaida','۞يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تَتَّخِذُواْ ٱلۡيَهُودَ وَٱلنَّصَٰرَىٰٓ أَوۡلِيَآءَۘ بَعۡضُهُمۡ أَوۡلِيَآءُ بَعۡضࣲۚ وَمَن يَتَوَلَّهُم مِّنكُمۡ فَإِنَّهُۥ مِنۡهُمۡۗ إِنَّ ٱللَّهَ لَا يَهۡدِي ٱلۡقَوۡمَ ٱلظَّٰلِمِينَ','اے ایمان والو! یہود اور نصاریٰ کو دوست نہ بناؤ یہ ایک دوسرے کے دوست ہیں اور جو شخص تم میں سے ان کو دوست بنائے گا وہ بھی انہیں میں سے ہوگا بیشک خدا ظالم لوگوں کو ہدایت نہیں دیتا','O believers! Take neither Jews nor Christians as guardians—they are guardians of each other. Whoever does so will be counted as one of them. Surely Allah does not guide the wrongdoing people','ऐ ईमानदारों यहूदियों और नसरानियों को अपना सरपरस्त न बनाओ (क्योंकि) ये लोग (तुम्हारे मुख़ालिफ़ हैं मगर) बाहम एक दूसरे के दोस्त हैं और (याद रहे कि) तुममें से जिसने उनको अपना सरपरस्त बनाया पस फिर वह भी उन्हीं लोगों में से हो गया बेशक ख़ुदा ज़ालिम लोगों को राहे रास्त पर नहीं लाता');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (5,52,'Al-Maaida','فَتَرَى ٱلَّذِينَ فِي قُلُوبِهِم مَّرَضࣱ يُسَٰرِعُونَ فِيهِمۡ يَقُولُونَ نَخۡشَىٰٓ أَن تُصِيبَنَا دَآئِرَةࣱۚ فَعَسَى ٱللَّهُ أَن يَأۡتِيَ بِٱلۡفَتۡحِ أَوۡ أَمۡرࣲ مِّنۡ عِندِهِۦ فَيُصۡبِحُواْ عَلَىٰ مَآ أَسَرُّواْ فِيٓ أَنفُسِهِمۡ نَٰدِمِينَ','تو جن لوگوں کے دلوں میں (نفاق کا) مرض ہے تم ان کو دیکھو گے کہ ان میں دوڑ دوڑ کے ملے جاتے ہیں کہتے ہیں کہ ہمیں خوف ہے کہ کہیں ہم پر زمانے کی گردش نہ آجائے سو قریب ہے کہ خدا فتح بھیجے یا اپنے ہاں سے کوئی اور امر (نازل فرمائے) پھر یہ اپنے دل کی باتوں پر جو چھپایا کرتے تھے پشیمان ہو کر رہ جائیں گے','You see those with sickness in their hearts racing for their guardianship, saying ˹in justification˺, “We fear a turn of fortune will strike us.” But perhaps Allah will bring about ˹your˺ victory or another favour by His command, and they will regret what they have hidden in their hearts','तो (ऐ रसूल) जिन लोगों के दिलों में (नेफ़ाक़ की) बीमारी है तुम उन्हें देखोगे कि उनमें दौड़ दौड़ के मिले जाते हैं और तुमसे उसकी वजह यह बयान करते हैं कि हम तो इससे डरते हैं कि कहीं ऐसा न हो उनके न (मिलने से) ज़माने की गर्दिश में न मुब्तिला हो जाएं तो अनक़रीब ही ख़ुदा (मुसलमानों की) फ़तेह या कोई और बात अपनी तरफ़ से ज़ाहिर कर देगा तब यह लोग इस बदगुमानी पर जो अपने जी में छिपाते थे शर्माएंगे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (5,53,'Al-Maaida','وَيَقُولُ ٱلَّذِينَ ءَامَنُوٓاْ أَهَٰٓؤُلَآءِ ٱلَّذِينَ أَقۡسَمُواْ بِٱللَّهِ جَهۡدَ أَيۡمَٰنِهِمۡ إِنَّهُمۡ لَمَعَكُمۡۚ حَبِطَتۡ أَعۡمَٰلُهُمۡ فَأَصۡبَحُواْ خَٰسِرِينَ','اور اس (وقت) مسلمان (تعجب سے) کہیں گے کہ کیا یہ وہی ہیں جو خدا کی سخت سخت قسمیں کھایا کرتے تھے کہ ہم تمہارے ساتھ ہیں ان کےعمل اکارت گئے اور وہ خسارے میں پڑ گئے','˹Only then,˺ the believers will ask ˹one another˺, “Are these the ones who swore solemn oaths by Allah that they were with you?” Their deeds have been in vain, so they have become losers','और मोमिनीन (जब उन पर नेफ़ाक़ ज़ाहिर हो जाएगा तो) कहेंगे क्या ये वही लोग हैं जो सख्त से सख्त क़समें खाकर (हमसे) कहते थे कि हम ज़रूर तुम्हारे साथ हैं उनका सारा किया धरा अकारत हुआ और सख्त घाटे में आ गए');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (5,54,'Al-Maaida','يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ مَن يَرۡتَدَّ مِنكُمۡ عَن دِينِهِۦ فَسَوۡفَ يَأۡتِي ٱللَّهُ بِقَوۡمࣲ يُحِبُّهُمۡ وَيُحِبُّونَهُۥٓ أَذِلَّةٍ عَلَى ٱلۡمُؤۡمِنِينَ أَعِزَّةٍ عَلَى ٱلۡكَٰفِرِينَ يُجَٰهِدُونَ فِي سَبِيلِ ٱللَّهِ وَلَا يَخَافُونَ لَوۡمَةَ لَآئِمࣲۚ ذَٰلِكَ فَضۡلُ ٱللَّهِ يُؤۡتِيهِ مَن يَشَآءُۚ وَٱللَّهُ وَٰسِعٌ عَلِيمٌ','اے ایمان والو اگر کوئی تم میں سے اپنے دین سے پھر جائے گا تو خدا ایسے لوگ پیدا کر دے گا جن کو وہ دوست رکھے اور جسے وہ دوست رکھیں اور جو مومنوں کے حق میں نرمی کریں اور کافروں سے سختی سے پیش آئیں خدا کی راہ میں جہاد کریں اور کسی ملامت کرنے والی کی ملامت سے نہ ڈریں یہ خدا کا فضل ہے وہ جسے چاہتا ہے دیتا ہے اور الله بڑی کشائش والا اور جاننے والا ہے','O believers! Whoever among you abandons their faith, Allah will replace them with others who love Him and are loved by Him. They will be humble with the believers but firm towards the disbelievers, struggling in the Way of Allah; fearing no blame from anyone. This is the favour of Allah. He grants it to whoever He wills. And Allah is All-Bountiful, All-Knowing','ऐ ईमानदारों तुममें से जो कोई अपने दीन से फिर जाएगा तो (कुछ परवाह नहीं फिर जाए) अनक़रीब ही ख़ुदा ऐसे लोगों को ज़ाहिर कर देगा जिन्हें ख़ुदा दोस्त रखता होगा और वह उसको दोस्त रखते होंगे ईमानदारों के साथ नर्म और मुन्किर (और) काफ़िरों के साथ सख्त ख़ुदा की राह में जेहाद करेंगे और किसी मलामत करने वाले की मलामत की कुछ परवाह न करेंगे ये ख़ुदा का फ़ज़ल (व करम) है वह जिसे चाहता हे देता है और ख़ुदा तो बड़ी गुन्जाइश वाला वाक़िफ़कार है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (5,55,'Al-Maaida','إِنَّمَا وَلِيُّكُمُ ٱللَّهُ وَرَسُولُهُۥ وَٱلَّذِينَ ءَامَنُواْ ٱلَّذِينَ يُقِيمُونَ ٱلصَّلَوٰةَ وَيُؤۡتُونَ ٱلزَّكَوٰةَ وَهُمۡ رَٰكِعُونَ','تمہارے دوست تو خدا اور اس کے پیغمبر اور مومن لوگ ہی ہیں جو نماز پڑھتے اور زکوٰة دیتے اور (خدا کے آگے) جھکتے ہیں','Your only guardians are Allah, His Messenger, and fellow believers—who establish prayer and pay alms-tax with humility','(ऐ ईमानदारों) तुम्हारे मालिक सरपरस्त तो बस यही हैं ख़ुदा और उसका रसूल और वह मोमिनीन जो पाबन्दी से नमाज़ अदा करते हैं और हालत रूकूउ में ज़कात देते हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (5,56,'Al-Maaida','وَمَن يَتَوَلَّ ٱللَّهَ وَرَسُولَهُۥ وَٱلَّذِينَ ءَامَنُواْ فَإِنَّ حِزۡبَ ٱللَّهِ هُمُ ٱلۡغَٰلِبُونَ','اور جو شخص خدا اور اس کے پیغمبر اور مومنوں سے دوستی کرے گا تو (وہ خدا کی جماعت میں داخل ہوگا اور) خدا کی جماعت ہی غلبہ پانے والی ہے','Whoever allies themselves with Allah, His Messenger, and fellow believers, then it is certainly Allah’s party that will prevail','और जिस शख्स ने ख़ुदा और रसूल और (उन्हीं) ईमानदारों को अपना सरपरस्त बनाया तो (ख़ुदा के लशकर में आ गया और) इसमें तो शक नहीं कि ख़ुदा ही का लशकर वर (ग़ालिब) रहता है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (5,57,'Al-Maaida','يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تَتَّخِذُواْ ٱلَّذِينَ ٱتَّخَذُواْ دِينَكُمۡ هُزُوࣰ ا وَلَعِبࣰ ا مِّنَ ٱلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ مِن قَبۡلِكُمۡ وَٱلۡكُفَّارَ أَوۡلِيَآءَۚ وَٱتَّقُواْ ٱللَّهَ إِن كُنتُم مُّؤۡمِنِينَ','اے ایمان والوں! جن لوگوں کو تم سے پہلے کتابیں دی گئی تھیں ان کو اور کافروں کو جنہوں نے تمہارے دین کو ہنسی اور کھیل بنا رکھا ہے دوست نہ بناؤ اور مومن ہو تو خدا سے ڈرتے رہو','O believers! Do not seek the guardianship of those given the Scripture before you and the disbelievers who have made your faith a mockery and amusement. And be mindful of Allah if you are ˹truly˺ believers','ऐ ईमानदारों जिन लोगों (यहूद व नसारा) को तुम से पहले किताबे (ख़ुदा तौरेत, इन्जील) दी जा चुकी है उनमें से जिन लोगों ने तुम्हारे दीन को हॅसी खेल बना रखा है उनको और कुफ्फ़ार को अपना सरपरस्त न बनाओ और अगर तुम सच्चे ईमानदार हो तो ख़ुदा ही से डरते रहो');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (5,58,'Al-Maaida','وَإِذَا نَادَيۡتُمۡ إِلَى ٱلصَّلَوٰةِ ٱتَّخَذُوهَا هُزُوࣰ ا وَلَعِبࣰ اۚ ذَٰلِكَ بِأَنَّهُمۡ قَوۡمࣱ لَّا يَعۡقِلُونَ','اور جب تم لوگ نماز کے لیے اذان دیتے ہو تو یہ اسے بھی ہنسی اور کھیل بناتے ہیں یہ اس لیے کہ سمجھ نہیں رکھتے','When you call to prayer, they mock it in amusement. This is because they are a people without understanding','और (उनकी शरारत यहॉ तक पहुंची) कि जब तुम (अज़ान देकर) नमाज़ के वास्ते (लोगों को) बुलाते हो ये लोग नमाज़ को हॅसी खेल बनाते हैं ये इस वजह से कि (लोग बिल्कुल बे अक्ल हैं) और कुछ नहीं समझते');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (5,59,'Al-Maaida','قُلۡ يَٰٓأَهۡلَ ٱلۡكِتَٰبِ هَلۡ تَنقِمُونَ مِنَّآ إِلَّآ أَنۡ ءَامَنَّا بِٱللَّهِ وَمَآ أُنزِلَ إِلَيۡنَا وَمَآ أُنزِلَ مِن قَبۡلُ وَأَنَّ أَكۡثَرَكُمۡ فَٰسِقُونَ','کہو کہ اے اہل کتاب! تم ہم میں برائی ہی کیا دیکھتے ہو سوا اس کے کہ ہم خدا پر اور جو (کتاب) ہم پر نازل ہوئی اس پر اور جو (کتابیں) پہلے نازل ہوئیں ان پر ایمان لائے ہیں اور تم میں اکثر بدکردار ہیں','Say, ˹O Prophet,˺ “O People of the Book! Do you resent us only because we believe in Allah and what has been revealed to us and what was revealed before—while most of you are rebellious?”','(ऐ रसूल अहले किताब से कहो कि) आख़िर तुम हमसे इसके सिवा और क्या ऐब लगा सकते हो कि हम ख़ुदा पर और जो (किताब) हमारे पास भेजी गयी है और जो हमसे पहले भेजी गयी ईमान लाए हैं और ये तुममें के अक्सर बदकार हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (5,60,'Al-Maaida','قُلۡ هَلۡ أُنَبِّئُكُم بِشَرࣲّ مِّن ذَٰلِكَ مَثُوبَةً عِندَ ٱللَّهِۚ مَن لَّعَنَهُ ٱللَّهُ وَغَضِبَ عَلَيۡهِ وَجَعَلَ مِنۡهُمُ ٱلۡقِرَدَةَ وَٱلۡخَنَازِيرَ وَعَبَدَ ٱلطَّٰغُوتَۚ أُوْلَٰٓئِكَ شَرࣱّ مَّكَانࣰ ا وَأَضَلُّ عَن سَوَآءِ ٱلسَّبِيلِ','کہو کہ میں تمہیں بتاؤں کہ خدا کے ہاں اس سے بھی بدتر جزا پانے والے کون ہیں؟ وہ لوگ ہیں جن پر خدا نے لعنت کی اور جن پر وہ غضبناک ہوا اور (جن کو) ان میں سے بندر اور سور بنا دیا اور جنہوں نے شیطان کی پرستش کی ایسے لوگوں کا برا ٹھکانہ ہے اور وہ سیدھے رستے سے بہت دور ہیں','Say, ˹O Prophet,˺ “Shall I inform you of those who deserve a worse punishment from Allah ˹than the rebellious˺? It is those who earned Allah’s condemnation and displeasure—some being reduced to apes and pigs and worshippers of false gods. These are far worse in rank and farther astray from the Right Way.”','(ऐ रसूल) तुम कह दो कि मैं तुम्हें ख़ुदा के नज़दीक सज़ा में इससे कहीं बदतर ऐब बता दूं (अच्छा लो सुनो) जिसपर ख़ुदा ने लानत की हो और उस पर ग़ज़ब ढाया हो और उनमें से किसी को (मसख़ करके) बन्दर और (किसी को) सूअर बना दिया हो और (ख़ुदा को छोड़कर) शैतान की परस्तिश की हो पस ये लोग दरजे में कहीं बदतर और राहे रास्त से भटक के सबसे ज्यादा दूर जा पहुंचे हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (5,61,'Al-Maaida','وَإِذَا جَآءُوكُمۡ قَالُوٓاْ ءَامَنَّا وَقَد دَّخَلُواْ بِٱلۡكُفۡرِ وَهُمۡ قَدۡ خَرَجُواْ بِهِۦۚ وَٱللَّهُ أَعۡلَمُ بِمَا كَانُواْ يَكۡتُمُونَ','اور جب یہ لوگ تمہارے پاس آتے ہیں تو کہتے ہیں کہ ہم ایمان لے آئے حالانکہ کفر لے کر آتے ہیں اور اسی کو لیکر جاتے ہیں اور جن باتوں کو یہ مخفی رکھتے ہیں خدا ان کو خوب جانتا ہے','When they come to you ˹believers˺ they say, “We believe.” But they are committed to disbelief when they enter and when they leave. And Allah knows what they hide','और (मुसलमानों) जब ये लोग तुम्हारे पास आ जाते हैं तो कहते हैं कि हम तो ईमान लाए हैं हालॉकि वह कुफ़्र ही को साथ लेकर आए और फिर निकले भी तो साथ लिए हुए और जो नेफ़ाक़ वह छुपाए हुए थे ख़ुदा उसे ख़ूब जानता है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (5,62,'Al-Maaida','وَتَرَىٰ كَثِيرࣰ ا مِّنۡهُمۡ يُسَٰرِعُونَ فِي ٱلۡإِثۡمِ وَٱلۡعُدۡوَٰنِ وَأَكۡلِهِمُ ٱلسُّحۡتَۚ لَبِئۡسَ مَا كَانُواْ يَعۡمَلُونَ','اور تم دیکھو گے کہ ان میں اکثر گناہ اور زیادتی اور حرام کھانے میں جلدی کر رہے ہیں بےشک یہ جو کچھ کرتے ہیں برا کرتے ہیں','You see many of them racing towards sin, transgression, and consumption of forbidden gain. Evil indeed are their actions','(ऐ रसूल) तुम उनमें से बहुतेरों को देखोगे कि गुनाह और सरकशी और हरामख़ोरी की तरफ़ दौड़ पड़ते हैं जो काम ये लोग करते थे वह यक़ीनन बहुत बुरा है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (5,63,'Al-Maaida','لَوۡلَا يَنۡهَىٰهُمُ ٱلرَّبَّٰنِيُّونَ وَٱلۡأَحۡبَارُ عَن قَوۡلِهِمُ ٱلۡإِثۡمَ وَأَكۡلِهِمُ ٱلسُّحۡتَۚ لَبِئۡسَ مَا كَانُواْ يَصۡنَعُونَ','بھلا ان کے مشائخ اور علماء انہیں گناہ کی باتوں اور حرام کھانے سے منع کیوں نہیں کرتے؟ بلاشبہ وہ بھی برا کرتے ہیں','Why do their rabbis and scholars not forbid them from saying what is sinful and consuming what is unlawful? Evil indeed is their inaction','उनको अल्लाह वाले और उलेमा झूठ बोलने और हरामख़ोरी से क्यों नहीं रोकते जो (दरगुज़र) ये लोग करते हैं यक़ीनन बहुत ही बुरी है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (5,64,'Al-Maaida','وَقَالَتِ ٱلۡيَهُودُ يَدُ ٱللَّهِ مَغۡلُولَةٌۚ غُلَّتۡ أَيۡدِيهِمۡ وَلُعِنُواْ بِمَا قَالُواْۘ بَلۡ يَدَاهُ مَبۡسُوطَتَانِ يُنفِقُ كَيۡفَ يَشَآءُۚ وَلَيَزِيدَنَّ كَثِيرࣰ ا مِّنۡهُم مَّآ أُنزِلَ إِلَيۡكَ مِن رَّبِّكَ طُغۡيَٰنࣰ ا وَكُفۡرࣰ اۚ وَأَلۡقَيۡنَا بَيۡنَهُمُ ٱلۡعَدَٰوَةَ وَٱلۡبَغۡضَآءَ إِلَىٰ يَوۡمِ ٱلۡقِيَٰمَةِۚ كُلَّمَآ أَوۡقَدُواْ نَارࣰ ا لِّلۡحَرۡبِ أَطۡفَأَهَا ٱللَّهُۚ وَيَسۡعَوۡنَ فِي ٱلۡأَرۡضِ فَسَادࣰ اۚ وَٱللَّهُ لَا يُحِبُّ ٱلۡمُفۡسِدِينَ','اور یہود کہتے ہیں کہ خدا کا ہاتھ (گردن سے) بندھا ہوا ہے (یعنی الله بخیل ہے) انہیں کے ہاتھ باندھے جائیں اور ایسا کہنے کے سبب ان پر لعنت ہو (اس کا ہاتھ بندھا ہوا نہیں) بلکہ اس کے دونوں ہاتھ کھلے ہیں وہ جس طرح (اور جتنا) چاہتا ہے خرچ کرتا ہے اور (اے محمد) یہ (کتاب) جو تمہارے پروردگار کی طرف سے تم پر نازل ہوئی اس سے ان میں سے اکثر کی شرارت اور انکار اور بڑھے گا اور ہم نے ان کے باہم عداوت اور بغض قیامت تک کے لیے ڈال دیا ہے یہ جب لڑائی کے لیے آگ جلاتے ہیں خدا اس کو بجھا دیتا ہے اور یہ ملک میں فساد کے لیے دوڑے پھرتے ہیں اور خدا فساد کرنے والوں کو دوست نہیں رکھتا','˹Some among˺ the Jews said, “Allah is tight-fisted.” May their fists be tied and they be condemned for what they said. Rather, He is open-handed, giving freely as He pleases. That which has been revealed to you ˹O Prophet˺ from your Lord will only cause many of them to increase in wickedness and disbelief. We have stirred among them hostility and hatred until the Day of Judgment. Whenever they kindle the fire of war, Allah puts it out. And they strive to spread corruption in the land. And Allah does not like corruptors','और यहूदी कहने लगे कि ख़ुदा का हाथ बॅधा हुआ है (बख़ील हो गया) उन्हीं के हाथ बॉध दिए जाएं और उनके (इस) कहने पर (ख़ुदा की) फिटकार बरसे (ख़ुदा का हाथ बॅधने क्यों लगा) बल्कि उसके दोनों हाथ कुशादा हैं जिस तरह चाहता है ख़र्च करता है और जो (किताब) तुम्हारे पास नाज़िल की गयी है (उनका शक व हसद) उनमें से बहुतेरों को कुफ़्र व सरकशी को और बढ़ा देगा और (गोया) हमने ख़ुद उनके आपस में रोज़े क़यामत तक अदावत और कीने की बुनियाद डाल दी जब ये लोग लड़ाई की आग भड़काते हैं तो ख़ुदा उसको बुझा देता है और रूए ज़मीन में फ़साद फेलाने के लिए दौड़ते फिरते हैं और ख़ुदा फ़सादियों को दोस्त नहीं रखता');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (5,65,'Al-Maaida','وَلَوۡ أَنَّ أَهۡلَ ٱلۡكِتَٰبِ ءَامَنُواْ وَٱتَّقَوۡاْ لَكَفَّرۡنَا عَنۡهُمۡ سَيِّـَٔاتِهِمۡ وَلَأَدۡخَلۡنَٰهُمۡ جَنَّٰتِ ٱلنَّعِيمِ','اور اگر اہل کتاب ایمان لاتے اور پرہیز گاری کرتے تو ہم ان سے ان کے گناہ محو کر دیتے اور ان کو نعمت کے باغوں میں داخل کرتے','Had the People of the Book only been faithful and mindful ˹of Allah˺, We would have certainly absolved them of their sins and admitted them into the Gardens of Bliss','और अगर अहले किताब ईमान लाते और (हमसे) डरते तो हम ज़रूर उनके गुनाहों से दरगुज़र करते और उनको नेअमत व आराम (बेहिशत के बाग़ों में) पहुंचा देते');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (5,66,'Al-Maaida','وَلَوۡ أَنَّهُمۡ أَقَامُواْ ٱلتَّوۡرَىٰةَ وَٱلۡإِنجِيلَ وَمَآ أُنزِلَ إِلَيۡهِم مِّن رَّبِّهِمۡ لَأَكَلُواْ مِن فَوۡقِهِمۡ وَمِن تَحۡتِ أَرۡجُلِهِمۚ مِّنۡهُمۡ أُمَّةࣱ مُّقۡتَصِدَةࣱۖ وَكَثِيرࣱ مِّنۡهُمۡ سَآءَ مَا يَعۡمَلُونَ','اور اگر وہ تورات اور انجیل کو اور جو (اور کتابیں) ان کے پروردگار کی طرف سے ان پر نازل ہوئیں ان کو قائم رکھتے (تو ان پر رزق مینہ کی طرح برستا کہ) اپنے اوپر سے پاؤں کے نیچے سے کھاتے ان میں کچھ لوگ میانہ رو ہیں اور بہت سے ایسے ہیں جن کے اعمال برے ہیں','And had they observed the Torah, the Gospel, and what has been revealed to them from their Lord, they would have been overwhelmed with provisions from above and below. Some among them are upright, yet many do nothing but evil','और अगर यह लोग तौरैत और इन्जील और (सहीफ़े) उनके पास उनके परवरदिगार की तरफ़ से नाज़िल किये गए थे (उनके एहकाम को) क़ायम रखते तो ज़रूर (उनके) ऊपर से भी (रिज़क़ बरस पड़ता) और पॉवों के नीचे से भी उबल आता और (ये ख़ूब चैन से) खाते उनमें से कुछ लोग तो एतदाल पर हैं (मगर) उनमें से बहुतेरे जो कुछ करते हैं बुरा ही करते हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (5,67,'Al-Maaida','۞يَٰٓأَيُّهَا ٱلرَّسُولُ بَلِّغۡ مَآ أُنزِلَ إِلَيۡكَ مِن رَّبِّكَۖ وَإِن لَّمۡ تَفۡعَلۡ فَمَا بَلَّغۡتَ رِسَالَتَهُۥۚ وَٱللَّهُ يَعۡصِمُكَ مِنَ ٱلنَّاسِۗ إِنَّ ٱللَّهَ لَا يَهۡدِي ٱلۡقَوۡمَ ٱلۡكَٰفِرِينَ','اے پیغمبر جو ارشادات خدا کی طرف سے تم پر نازل ہوئے ہیں سب لوگوں کو پہنچا دو اور اگر ایسا نہ کیا تو تم خدا کے پیغام پہنچانے میں قاصر رہے (یعنی پیغمبری کا فرض ادا نہ کیا) اور خدا تم کو لوگوں سے بچائے رکھے گا بیشک خدا منکروں کو ہدایت نہیں دیتا','O Messenger! Convey everything revealed to you from your Lord. If you do not, then you have not delivered His message. Allah will ˹certainly˺ protect you from the people. Indeed, Allah does not guide the people who disbelieve','ऐ रसूल जो हुक्म तुम्हारे परवरदिगार की तरफ़ से तुम पर नाज़िल किया गया है पहुंचा दो और अगर तुमने ऐसा न किया तो (समझ लो कि) तुमने उसका कोई पैग़ाम ही नहीं पहुंचाया और (तुम डरो नहीं) ख़ुदा तुमको लोगों के श्शर से महफ़ूज़ रखेगा ख़ुदा हरगिज़ काफ़िरों की क़ौम को मंज़िले मक़सूद तक नहीं पहुंचाता');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (5,68,'Al-Maaida','قُلۡ يَٰٓأَهۡلَ ٱلۡكِتَٰبِ لَسۡتُمۡ عَلَىٰ شَيۡءٍ حَتَّىٰ تُقِيمُواْ ٱلتَّوۡرَىٰةَ وَٱلۡإِنجِيلَ وَمَآ أُنزِلَ إِلَيۡكُم مِّن رَّبِّكُمۡۗ وَلَيَزِيدَنَّ كَثِيرࣰ ا مِّنۡهُم مَّآ أُنزِلَ إِلَيۡكَ مِن رَّبِّكَ طُغۡيَٰنࣰ ا وَكُفۡرࣰ اۖ فَلَا تَأۡسَ عَلَى ٱلۡقَوۡمِ ٱلۡكَٰفِرِينَ','کہو کہ اے اہل کتاب! جب تک تم تورات اور انجیل کو اور جو (اور کتابیں) تمہارے پروردگار کی طرف سے تم لوگوں پر نازل ہوئیں ان کو قائم نہ رکھو گے کچھ بھی راہ پر نہیں ہو سکتے اور یہ (قرآن) جو تمہارے پروردگار کی طرف سے تم پر نازل ہوا ہے ان میں سے اکثر کی سرکشی اور کفر اور بڑھے گا تو تم قوم کفار پر افسوس نہ کرو','Say, ˹O Prophet,˺ “O People of the Book! You have nothing to stand on unless you observe the Torah, the Gospel, and what has been revealed to you from your Lord.” And your Lord’s revelation to you ˹O Prophet˺ will only cause many of them to increase in wickedness and disbelief. So do not grieve for the people who disbelieve','(ऐ रसूल) तुम कह दो कि ऐ अहले किताब जब तक तुम तौरेत और इन्जील और जो (सहीफ़े) तुम्हारे परवरदिगार की तरफ़ से तुम पर नाज़िल हुए हैं उनके (एहकाम) को क़ायम न रखोगे उस वक्त तक तुम्हारा मज़बह कुछ भी नहीं और (ऐ रसूल) जो (किताब) तुम्हारे पास तुम्हारे परवरदिगार की तरफ़ से भेजी गयी है (उसका) रश्क (हसद) उनमें से बहुतेरों की सरकशी व कुफ़्र को और बढ़ा देगा तुम काफ़िरों के गिरोह पर अफ़सोस न करना');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (5,69,'Al-Maaida','إِنَّ ٱلَّذِينَ ءَامَنُواْ وَٱلَّذِينَ هَادُواْ وَٱلصَّٰبِـُٔونَ وَٱلنَّصَٰرَىٰ مَنۡ ءَامَنَ بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِ وَعَمِلَ صَٰلِحࣰ ا فَلَا خَوۡفٌ عَلَيۡهِمۡ وَلَا هُمۡ يَحۡزَنُونَ','جو لوگ خدا پر اور روز آخرت پر ایمان لائیں گے اور عمل نیک کریں گے خواہ وہ مسلمان ہوں یا یہودی یا ستارہ پرست یا عیسائی ان کو (قیامت کے دن) نہ کچھ خوف ہو گا اور نہ غمناک ہوں گے','Indeed, the believers, Jews, Sabians and Christians—whoever ˹truly˺ believes in Allah and the Last Day and does good, there will be no fear for them, nor will they grieve','इसमें तो शक ही नहीं कि मुसलमान हो या यहूदी हकीमाना ख्याल के पाबन्द हों ख्वाह नसरानी (गरज़ कुछ भी हो) जो ख़ुदा और रोज़े क़यामत पर ईमान लाएगा और अच्छे (अच्छे) काम करेगा उन पर अलबत्ता न तो कोई ख़ौफ़ होगा न वह लोग आज़ुर्दा ख़ातिर होंगे');
